<!--vbase-->
<template>
  <div class="line-item-container ml-16 q-mr-sm" v-if="line_item_loaded">
    <div class="lineItems">
      <div class="accounting-fields-container accounting-table-header">
        <div class="width-40 p-4">Pos</div>

        <div class="flex-1">
          <div class="row">
            <div
              class="p-4"
              :class="
                isMultiTaxSection ? 'primary-field' : 'primary-three-field'
              "
            >
              {{ $t('accounts') }}
            </div>
            <div
              class="p-4"
              :class="
                isMultiTaxSection ? 'primary-field' : 'primary-three-field'
              "
            >
              {{ $t('booking_reference') }}
            </div>
            <div
              class="p-4"
              :class="
                isMultiTaxSection ? 'secondary-field' : 'primary-three-field'
              "
            >
              <div class="row">
                <div v-if="isMultiTaxSection" class="col-5 p-4">
                  {{ $t('tax_code_country') }}
                </div>
                <div
                  class="p-4"
                  :class="isMultiTaxSection ? 'col-7' : 'col-12'"
                >
                  {{ $t('amount_title') }}
                </div>
              </div>
            </div>
          </div>
        </div>

        <div v-if="!is_view_readonly" class="w-75px p-4"></div>
      </div>

      <div v-if="false && hasAdditionalFields()" class="header">
        <div
          v-for="(field, index) in accounting_additional_fields"
          :key="index"
          :style="dynamicAdditionalFieldStyle as any"
        >
          {{ displayFieldLabel(field) }}
        </div>
      </div>

      <div class="accounting-fields-area">
        <template v-if="isMultiTaxSection">
          <template v-if="accounting_mode != 'line_items'">
            <template v-for="(item, index) in lineItems" :key="item">
              <template v-if="item.type == 'total_line_item'">
                <MuLtiTaxSection
                  :index="index"
                  :additional_field_error="
                    lineItems[index].additional_field_error
                  "
                />
              </template>
            </template>
          </template>
        </template>

        <TotalLineItem
          :additional_field_error="lineItems[0].additional_field_error"
          v-else
        />
      </div>

      <template v-if="accounting_mode === 'line_items'">
        <template v-for="(item, index) in lineItems" :key="item">
          <template v-if="item.type === 'line_item'">
            <lineItem
              :index="index"
              :additional_field_error="lineItems[index].additional_field_error"
            />
            <q-separator class="q-mt-sm" />
          </template>
        </template>
        <div class="row items-center q-mt-sm">
          <div style="width: 3%">
            <div
              class="q-ma-sm bg-primary primary-bg-text"
              style="width: 22px; display: inline-block"
            >
              <q-icon
                name="add"
                size="22px"
                @click="addLineItem()"
                @keydown.enter="addLineItem()"
                tabindex="1"
                class="cursor-pointer"
                :class="is_view_readonly ? 'disabled' : ''"
              >
                <q-tooltip>{{ $t('add_new_line_item') }}</q-tooltip>
              </q-icon>
            </div>
          </div>
          <div style="width: 97%"></div>
        </div>
      </template>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import stringUtil from 'src/utils/string';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import {
  useSettingStore,
  useAutoAccountingStore,
  useAccountingTypeStore,
} from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';
import { isEmptyString, objLen } from 'src/utils/general';
import lineItem from 'src/pages/AutoAccounting/Detail/Templates/LN/lineItem.vue';
import TotalLineItem from 'src/pages/AutoAccounting/Detail/Templates/LN/TotalLineItem.vue';
import MuLtiTaxSection from 'src/pages/AutoAccounting/Detail/Templates/LN/MuLtiTaxSection.vue';
import displayFieldLabelMixin from 'src/utils/displayFieldLabel.js';
export default defineComponent({
  el: '#app',
  mixins: [stringUtil, helperMixin, displayFieldLabelMixin],
  components: {
    lineItem,
    TotalLineItem,
    MuLtiTaxSection,
  },
  watch: {},
  emits: ['addLineItem'],
  mounted() {
    this.init();
    document.addEventListener('reload_accounts', () => {
      this.reloadAccounts();
    });
  },

  unmounted: function () {
    document.removeEventListener('reload_accounts', () => {
      this.reloadAccounts();
    });
  },
  data() {
    return {
      objLen,
    };
  },
  methods: {
    async init() {
      try {
        if (!isEmptyString(this.accounting_error)) {
          return;
        }
        await this.startSettingsFetch();
        await this.fetchLnAccountsPromise();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.accounting_error = msg;
      } finally {
        // this.resolveAccountLoadingPromise();
      }
    },

    addLineItem() {
      // trigger event
      this.$emit('addLineItem');
    },
    async reloadAccounts() {
      await this.reloadLnAccounts();
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      lineItems,
      accounting_mode,
      is_view_readonly,
      accounting_error,
      isMultiTaxSection,
    } = storeToRefs(auto_accounting_store);

    const { fetchLnAccountsPromise, reloadLnAccounts } = auto_accounting_store;

    const accounting_type_store = useAccountingTypeStore();
    const { line_item_loaded, accounting_additional_fields } = storeToRefs(
      accounting_type_store,
    );
    const { hasAdditionalFields, dynamicAdditionalFieldStyle } =
      accounting_type_store;

    const settings_store = useSettingStore();
    const { startSettingsFetch } = settings_store;
    const { user_settings } = storeToRefs(settings_store);

    return {
      reloadLnAccounts,
      dynamicAdditionalFieldStyle,
      fetchLnAccountsPromise,
      hasAdditionalFields,
      startSettingsFetch,
      accounting_additional_fields,
      user_settings,
      is_view_readonly,
      accounting_error,
      lineItems,
      isMultiTaxSection,
      accounting_mode,
      line_item_loaded,
    };
  },
});
</script>
