<template>
  <div>
    <q-input
      tabindex="1"
      outlined
      dense
      v-model="lineItems[index].amount"
      :readonly="isReadOnly()"
      @update:model-value="
        (e: any) => {
          amountUpdated();
        }
      "
    >
      <template v-slot:append>
        <q-icon
          v-if="lineItems[index]['amount_error'] !== ''"
          flat
          dense
          name="error"
          size="24px"
          color="red"
        >
          <q-tooltip class="bg-red" anchor="bottom right" self="top right">
            {{ lineItems[index]['amount_error'] }}
          </q-tooltip>
        </q-icon>
      </template>
    </q-input>
    <q-tooltip>{{ lineItems[index].amount }}</q-tooltip>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useAutoAccountingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import { validateAmount } from 'src/utils/validateRegex';

export default defineComponent({
  mixins: [],
  props: {
    index: {
      type: Number,
      required: true,
    },
  },
  components: {},
  methods: {
    isReadOnly() {
      if (this.lineItems[this.index].split_items.length > 0) {
        return true;
      }

      if (
        this.lineItems[this.index].hasOwnProperty('amount_readonly') &&
        this.lineItems[this.index].amount_readonly === true
      ) {
        return true;
      }

      if (this.lineItems[this.index].readonly) {
        return true;
      }

      if (this.is_view_readonly) {
        return true;
      }

      return false;
    },

    clearlineItemAmountError(index: number) {
      this.lineItems[index].amount_error = '';
    },

    amountUpdated() {
      if (this.is_view_readonly) {
        return;
      }

      this.clearlineItemAmountError(this.index);
      if (!this.lineItems[this.index]) {
        this.lineItems[this.index].amount_error = this.$t('amount_is_empty');
      }

      if (!validateAmount(this.lineItems[this.index].amount)) {
        this.lineItems[this.index].amount_error = this.$t('amount_invalid');

        return;
      }

      this.calculateTotalByMode();
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const { lineItems, amount_format_locale, is_view_readonly } = storeToRefs(
      auto_accounting_store,
    );
    const { calculateTotalByMode } = auto_accounting_store;

    return {
      calculateTotalByMode,
      is_view_readonly,
      amount_format_locale,
      lineItems,
    };
  },
});
</script>
<style scoped lang="scss"></style>
