<template>
  <q-input
    tabindex="1"
    class="q-pl-sm"
    outlined
    dense
    v-model="
      lineItems[line_item_index].split_items[split_line_index].percentage
    "
    @keyup.enter="
      handlePercdntEnter(
        lineItems[line_item_index].split_items[split_line_index],
      )
    "
    :readonly="is_view_readonly ? true : false"
  >
    <template v-slot:append>
      <q-icon
        v-if="
          lineItems[line_item_index].split_items[split_line_index][
            'percentage_error'
          ] !== ''
        "
        flat
        dense
        name="error"
        size="24px"
        color="red"
      >
        <q-tooltip class="bg-red" anchor="bottom right" self="top right">
          {{
            lineItems[line_item_index].split_items[split_line_index][
              'percentage_error'
            ]
          }}
        </q-tooltip>
      </q-icon>
    </template>
    <q-tooltip>
      {{ lineItems[line_item_index].split_items[split_line_index].percentage }}
    </q-tooltip>
  </q-input>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useAutoAccountingStore, useAmountFormatStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { validateAmount } from 'src/utils/validateRegex';

export default defineComponent({
  mixins: [],
  props: {
    line_item_index: {
      type: Number,
      required: true,
    },
    split_line_index: {
      type: Number,
      required: true,
    },
  },
  components: {},
  methods: {
    clearErrors(item: dynamicObj) {
      item.percentage_error = '';
    },
    //using
    validateAmountAndSetError(item: dynamicObj, value_float: any) {
      if (!value_float) {
        item.amount_error = this.$t('amount_is_empty');
        return false;
      }

      if (!validateAmount(value_float, true)) {
        item.amount_error = this.$t('amount_invalid');
        return false;
      }

      return true;
    },

    // using
    validatePercentAndSetError(item: dynamicObj, percent: string) {
      if (!percent) {
        item.percentage_error = this.$t('percentage_is_empty');
        return false;
      }

      if (!validateAmount(percent)) {
        item.percentage_error = this.$t('percentage_invalid');
        return false;
      }
      return true;
    },
    // using
    validatePercentUpdateAndSetError(item: dynamicObj, percent_float: number) {
      // `!percent_float` also rejected a legitimate 0 %, which is a real
      // workflow ("mark the part as 0 %"). Only a value that could not be
      // parsed into a number means "no percentage was entered"; the empty
      // input itself is caught earlier, in handlePercdntEnter.
      if (Number.isNaN(percent_float)) {
        item.percentage_error = this.$t('percentage_is_empty');
        return false;
      }

      if (percent_float > 100) {
        item.percentage_error = this.$t(
          'percentage_cannot_be_greater_than_100',
        );
        return false;
      }
      return true;
    },

    async handlePercdntEnter(item: dynamicObj) {
      if (this.is_view_readonly) {
        return;
      }

      this.clearErrors(item);
      // check if percent field is empty or amount field is empty then do nothing
      let line_item_amount = this.lineItems[this.line_item_index].amount;
      let item_percentage = item.percentage.replace('%', '');

      // An empty field is the only "no percentage entered" case. Checking it
      // here keeps `0` a valid value further down without loosening the
      // empty-input error.
      if (item_percentage.trim() === '') {
        item.percentage_error = this.$t('percentage_is_empty');
        return;
      }

      if (!this.validateAmountAndSetError(item, line_item_amount)) {
        return;
      }

      const values = [];
      values.push({
        key: line_item_amount,
        value: line_item_amount,
      });

      values.push({
        key: item_percentage,
        value: item_percentage,
      });

      const formatted_values = await this.formatMultiValues(
        values,
        this.amount_format_locale,
      );

      const percent = this.searchValueByKey(item_percentage, formatted_values);
      const percent_float = parseFloat(percent);
      if (!this.validatePercentUpdateAndSetError(item, percent_float)) {
        return;
      }

      item.percent_float = percent_float;
      // Write the formatted percentage back into the field. Without this the
      // raw user input ("50") stayed in the input and the `%` sign the user
      // overwrote was never restored (KSB-35). Same convention as the sibling
      // Amount.vue field and the store's equal-split path.
      item.percentage =
        (await this.formatValue(
          percent_float.toFixed(2),
          'en_US',
          this.amount_format_locale,
        )) + '%';

      const line_item_amount_formatted = this.searchValueByKey(
        line_item_amount,
        formatted_values,
      );
      const line_item_amount_float = parseFloat(line_item_amount_formatted);
      this.lineItems[this.line_item_index].amount_standard =
        line_item_amount_float;

      const result = (percent_float / 100) * line_item_amount_float;
      const result_float = parseFloat(result.toFixed(2));
      const isNanValue = isNaN(result_float);
      if (isNanValue) {
        item.amount = '';
        return;
      }

      item.amount_standard = result_float;
      item.amount = await this.formatValue(
        String(result_float),
        'en_US',
        this.amount_format_locale,
      );

      this.autFillEmptyLineItems(this.line_item_index);
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const { lineItems, amount_format_locale, is_view_readonly } = storeToRefs(
      auto_accounting_store,
    );

    const { searchValueByKey, autFillEmptyLineItems } = auto_accounting_store;

    const amount_format_store = useAmountFormatStore();
    const { formatMultiValues, formatValue } = amount_format_store;

    return {
      autFillEmptyLineItems,
      searchValueByKey,
      is_view_readonly,
      formatMultiValues,
      formatValue,
      amount_format_locale,
      lineItems,
    };
  },
});
</script>
