<template>
  <div
    class="accounting-fields-container"
    :id="lineItems[index].id"
    :data-id="lineItems[index].id"
  >
    <div class="width-40 text-align-center p-4 p-t-10">
      <span v-if="lineItems[index].hasOwnProperty('position')">
        {{ lineItems[index].position }}
      </span>
    </div>

    <div class="flex-1">
      <div class="row">
        <div
          class="p-4"
          :class="isMultiTaxSection ? 'primary-field' : 'primary-three-field'"
        >
          <Account
            :readonly="lineItems[index].readonly"
            v-on:update-account="updateAccount"
            :item="lineItems[index]"
            :index="index"
          />
        </div>
        <div
          class="p-4"
          :class="isMultiTaxSection ? 'primary-field' : 'primary-three-field'"
        >
          <q-input
            class="full-width"
            tabindex="1"
            outlined
            dense
            v-model="lineItems[index].booking_reference"
            :readonly="
              lineItems[index].split_items.length > 0 || is_view_readonly
            "
            maxlength="30"
          >
            <template v-slot:append>
              <q-icon
                flat
                dense
                name="error"
                size="24px"
                color="red"
                v-if="false"
              >
                <q-tooltip
                  class="bg-red"
                  anchor="bottom right"
                  self="top right"
                >
                  {{ $t('field_required') }}
                </q-tooltip>
              </q-icon>
              <div
                class="char-counter"
                v-if="lineItems[index].booking_reference"
              >
                {{ lineItems[index].booking_reference.length }} / 30
              </div>
            </template>
          </q-input>
          <q-tooltip v-if="lineItems[index].booking_reference">{{
            lineItems[index].booking_reference
          }}</q-tooltip>
        </div>

        <div
          :class="isMultiTaxSection ? 'secondary-field' : 'primary-three-field'"
        >
          <div class="row">
            <div v-if="isMultiTaxSection" class="col-5 p-4">
              <q-select
                tabindex="1"
                class="ellipsify"
                emit-value
                map-options
                outlined
                dense
                v-model="lineItems[index].position"
                :options="taxCodeDropdown as any"
                :readonly="
                  lineItems[index].split_items.length > 0 || is_view_readonly
                "
              >
              </q-select>
            </div>
            <div class="p-4" :class="isMultiTaxSection ? 'col-7' : 'col-12'">
              <Amount :index="index" />
            </div>
          </div>
        </div>
      </div>
    </div>

    <div v-if="!is_view_readonly" class="w-75px p-4 p-t-10">
      <SplitLineItemBtn :index="index" />
      <UnSplitLineItemBtn :index="index" />
      <AddChildLineItem :index="index" />
    </div>
  </div>

  <div class="row">
    <div class="width-40"></div>

    <div class="flex-1">
      <Dimensions :index="index" />
    </div>
    <div v-if="!is_view_readonly" class="w-75px"></div>
  </div>

  <div v-if="false && hasAdditionalFields()" class="q-pr-sm primary-field">
    <div
      v-for="(field, field_index) in accounting_additional_fields"
      :key="field_index"
      :style="dynamicAdditionalFieldStyle as any"
    >
      <q-input
        v-if="lineItems[index].hasOwnProperty(field.field_name)"
        class="accouting-input column inline full-width"
        outlined
        v-model="lineItems[index][field.field_name]"
        :readonly="lineItems[index].split_items.length > 0 || is_view_readonly"
        :counter="!!getFieldMaxLength(field.field_name)"
        :maxlength="getFieldMaxLength(field.field_name)"
      >
        <template v-slot:append>
          <q-icon
            v-if="showErrorIcon(field.field_name, additional_field_error)"
            flat
            dense
            name="error"
            size="24px"
            color="red"
          >
            <q-tooltip class="bg-red" anchor="bottom right" self="top right">
              {{ $t('field_required') }}
            </q-tooltip>
          </q-icon>
        </template>
      </q-input>
    </div>
  </div>

  <div class="total-line-item-area full-width">
    <SplitedLineItems
      :index="index"
      :additional_field_error="lineItems[index].split_items"
    />
  </div>

  <div class="row q-pt-sm" v-if="lineItems[index].split_items.length > 0">
    <div class="width-40"></div>

    <div class="flex-1">
      <div class="row">
        <div class="primary-field p-4"></div>
        <div class="primary-field p-4"></div>
        <div class="secondary-field p-4">
          <span class="q-mr-md"> {{ $t('unsettled_amount') }}: </span>
          <span
            style="margin-left: 12px"
            v-if="lineItems[index].hasOwnProperty('pending_amount')"
          >
            {{ lineItems[index].pending_amount }}
          </span>
          <q-icon
            v-if="lineItems[index].error !== ''"
            flat
            dense
            name="error"
            size="20px"
            color="red"
            class="q-ml-sm"
          >
            <q-tooltip class="bg-red" anchor="bottom right" self="top right">
              {{ lineItems[index].error }}
            </q-tooltip>
          </q-icon>
        </div>
      </div>
    </div>
    <div v-if="!is_view_readonly" class="w-75px"></div>
  </div>
</template>

<script lang="ts">
const path = 'src/pages/AutoAccounting/Detail';

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import Amount from 'src/pages/AutoAccounting/Detail/lineItem/Amount.vue';
import Account from 'src/pages/AutoAccounting/Detail/components/Account.vue';
import Dimensions from 'src/pages/AutoAccounting/Detail/lineItem/Dimensions.vue';
import AddChildLineItem from 'src/pages/AutoAccounting/Detail/lineItem/AddChildLineItem.vue';
import SplitLineItemBtn from 'src/pages/AutoAccounting/Detail/lineItem/SplitLineItemBtn.vue';
import {
  useAccountingTypeStore,
  useAutoAccountingStore,
  useSettingStore,
} from 'src/store/main';
import SplitedLineItems from 'src/pages/AutoAccounting/Detail/Templates/LN/SplitedLineItems.vue';
import UnSplitLineItemBtn from 'src/pages/AutoAccounting/Detail/lineItem/UnSplitLineItemBtn.vue';
import { objLen } from 'src/utils/general';
import cache from 'src/utils/cache';

export default defineComponent({
  mixins: [cache],
  props: {
    index: {
      type: Number,
      required: true,
    },
    additional_field_error: {
      type: Array,
      default: () => [],
    },
  },
  data() {
    return {
      objLen,
    };
  },
  components: {
    SplitedLineItems,
    Dimensions,
    Amount,
    Account,
    AddChildLineItem,
    SplitLineItemBtn,
    UnSplitLineItemBtn,
  },
  methods: {
    updateAccount(newValue: any) {
      if (this.is_view_readonly) {
        return;
      }

      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      this.updateAccountInStore(this.index, null, newValue.value);
    },

    updateAmount(newValue: any) {
      if (this.is_view_readonly || this.index === null) {
        return;
      }

      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      this.lineItems[this.index].amount = newValue.value;
    },

    getFieldMaxLength(field_name: string) {
      const valid_booking_reference = this.user_settings[
        'AUTO_ACCOUNTING_FIELDS'
      ] as string;
      const fieldsConfig = JSON.parse(valid_booking_reference);

      const fieldConfig = fieldsConfig.find(
        (fieldConfig: any) => fieldConfig.field_name === field_name,
      );
      if (!fieldConfig || !fieldConfig.validation_rules) {
        return undefined;
      }

      const maxLengthRule = fieldConfig.validation_rules.find(
        (rule: any) => rule.rule === 'max_length',
      );
      if (!maxLengthRule) {
        return undefined;
      }

      return maxLengthRule.value as number;
    },

    showErrorIcon(field_name: string, additional_field_error: any) {
      return (
        Array.isArray(additional_field_error) &&
        additional_field_error.some((error: any) => error.field === field_name)
      );
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      lineItems,
      is_view_readonly,
      isMultiTaxSection,
      taxCodeDropdown,
    } = storeToRefs(auto_accounting_store);
    const {
      getDimensionsForAccount,
      validateLine,
      updateAccount: updateAccountInStore,
    } = auto_accounting_store;

    const accounting_type_store = useAccountingTypeStore();
    const { accounting_additional_fields } = storeToRefs(accounting_type_store);
    const { hasAdditionalFields, dynamicAdditionalFieldStyle } =
      accounting_type_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    return {
      user_settings,
      isMultiTaxSection,
      taxCodeDropdown,
      accounting_additional_fields,
      dynamicAdditionalFieldStyle,
      getDimensionsForAccount,
      updateAccountInStore,
      hasAdditionalFields,
      validateLine,
      is_view_readonly,
      lineItems,
    };
  },
});
</script>
<style scoped lang="scss"></style>
