<template>
  <q-select
    class="fixed-q-select"
    v-if="hasList"
    tabindex="1"
    use-input
    fill-input
    hide-selected
    outlined
    dense
    v-model="localValue"
    :loading="!accounts_loaded"
    :options="dimension_options"
    @filter="filterListEvent"
    @input-value="selectInputValue"
    emit-value
    map-options
    :readonly="is_view_readonly"
    :label="
      formatTextAndTranslate(item.name, ' ', '_') +
      (item.rule.toLowerCase() === 'm' ? ' *' : '')
    "
  >
    <template v-slot:label>
      {{ formatTextAndTranslate(item.name, ' ', '_') }}
      <span v-if="item.rule.toLowerCase() === 'm'" class="text-red"> *</span>
    </template>
    <template v-slot:selected-item="scope">
      <div class="ellipsis">{{ scope.opt.label }}</div>
      <q-tooltip v-if="localValue">{{ scope.opt.label }}</q-tooltip>
    </template>

    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps">
        <q-item-section>
          <q-item-label>
            <span v-html="highlightOption(scope.opt.label, input_value)"></span
          ></q-item-label>
        </q-item-section>
      </q-item>
    </template>
    <template v-slot:append>
      <q-icon
        v-if="dimension_error !== ''"
        flat
        dense
        name="error"
        size="24px"
        color="red"
      >
        <q-tooltip class="bg-red" anchor="bottom right" self="top right">
          <span v-html="dimension_error"></span>
        </q-tooltip>
      </q-icon>
    </template>
  </q-select>
  <q-input
    v-if="!hasList"
    tabindex="1"
    class="full-width"
    outlined
    dense
    :label="
      formatTextAndTranslate(item.name, ' ', '_') +
      (item.rule.toLowerCase() === 'm' ? '*' : '')
    "
    v-model="localValue"
    :readonly="is_view_readonly ? true : false"
  >
    <template v-slot:label>
      {{ formatTextAndTranslate(item.name, ' ', '_') }}
      <span v-if="item.rule.toLowerCase() === 'm'" class="text-red"> *</span>
    </template>
    <template v-slot:append>
      <q-icon
        v-if="dimension_error !== ''"
        flat
        dense
        name="error"
        size="24px"
        color="red"
      >
        <q-tooltip class="bg-red" anchor="bottom right" self="top right">
          <span v-html="dimension_error"></span>
        </q-tooltip>
      </q-icon>
    </template>
    <q-tooltip v-if="localValue">{{ localValue }}</q-tooltip>
  </q-input>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import displayFieldLabel from 'src/utils/displayFieldLabel.js';
import { isEmptyString, isUndefinedOrNull, objLen } from 'src/utils/general';
import { useAccountingTypeStore, useAutoAccountingStore } from 'src/store/main';

export default defineComponent({
  mixins: [displayFieldLabel],
  emits: ['update-dimension'],
  props: {
    item: {
      type: Object,
      required: true,
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    index: {
      type: Number,
      required: true,
    },
    account: {
      type: Object,
      required: true,
    },
  },
  watch: {
    dimension_dropdowns: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.setDropDownOptions();
      },
    },
  },
  components: {},
  computed: {
    dimension_error: function (): string {
      return String(this.item.error);
    },
    localValue: {
      get() {
        return String(this.item.value);
      },
      set(newValue: any) {
        this.$emit('update-dimension', { index: this.index, value: newValue });
      },
    },
    hasList: function (): boolean {
      if (objLen(this.account) === 0) {
        return false;
      }

      if (this.view_template == this.view_types.m3) {
        // if range dimension has options or general dimension has options
        // or if not in range in use general
        return this.hasDimensionByAccount();
      }

      if (
        this.dimension_dropdowns.hasOwnProperty(this.item.id) &&
        this.dimension_dropdowns[this.item.id].length > 0
      ) {
        return true;
      }
      return false;
    },
  },
  mounted: function () {
    this.dimension_value = this.item.value;
    this.input_value = '';
    this.setDropDownOptions();
  },
  methods: {
    setDropDownOptions() {
      if (objLen(this.account) === 0) {
        this.resetOptions();
        return;
      }

      if (this.view_template == this.view_types.m3) {
        this.getDimenionOptionbyAccount();
        return;
      }

      if (
        this.dimension_dropdowns.hasOwnProperty(this.item.id) &&
        this.dimension_dropdowns[this.item.id].length > 0
      ) {
        this.all_dimension_options = this.dimension_dropdowns[
          this.item.id
        ] as dynamicObj[];
        this.setDimensionOptions();
        return;
      }

      this.resetOptions();
    },

    resetOptions() {
      this.all_dimension_options = [] as dynamicObj[];
      this.dimension_options = this.all_dimension_options;
    },

    setDimensionOptions() {
      this.dimension_options = JSON.parse(
        JSON.stringify(this.all_dimension_options),
      );
    },

    hasDimensionByAccount() {
      let has_dimension_options = false;

      // check range dimensions
      const is_range_dimension = this.isRangeDimension();
      if (is_range_dimension && this.isRangeDimensionHasOptions()) {
        has_dimension_options = true;
      }

      // check general dimensions
      if (
        !has_dimension_options &&
        !is_range_dimension &&
        this.isGeneralDimension()
      ) {
        has_dimension_options = true;
      }

      return has_dimension_options;
    },

    isGeneralDimension() {
      if (
        this.dimension_general_dropdowns.hasOwnProperty(this.item.id) &&
        this.dimension_general_dropdowns[this.item.id].length > 0
      ) {
        return true;
      }

      return false;
    },

    isRangeDimensionHasOptions() {
      if (
        this.dimension_dropdowns.hasOwnProperty(this.account.value) &&
        this.dimension_dropdowns[this.account.value].hasOwnProperty(
          this.item.id,
        )
      ) {
        return true;
      }
      return false;
    },

    isRangeDimension() {
      if (
        this.dimension_rules.hasOwnProperty(this.account.value) &&
        this.dimension_rules[this.account.value].hasOwnProperty(this.item.id)
      ) {
        return true;
      }

      return false;
    },

    getDimenionOptionbyAccount() {
      if (!this.hasDimensionByAccount()) {
        this.resetOptions();
        return;
      }

      const is_range_dimension = this.isRangeDimension();
      if (is_range_dimension && this.isRangeDimensionHasOptions()) {
        this.all_dimension_options = this.dimension_dropdowns[
          this.account.value
        ][this.item.id] as dynamicObj[];
      }

      if (!is_range_dimension && this.isGeneralDimension()) {
        this.all_dimension_options = this.dimension_general_dropdowns[
          this.item.id
        ] as dynamicObj[];
      }

      this.setDimensionOptions();
    },

    filterListEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.setDimensionOptions();
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        let filtered = this.all_dimension_options.filter((v: dynamicObj) => {
          return v.label.toLowerCase().startsWith(needle);
        });

        if (filtered.length === 0) {
          filtered = this.all_dimension_options.filter((v: dynamicObj) => {
            return v.label.toLowerCase().indexOf(needle) > -1;
          });
        }

        this.dimension_options = filtered;
      });
    },

    // Auto-Complete
    selectInputValue(value: any) {
      this.input_value = value;
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      dimension_dropdowns,
      dimension_rules,
      accounts_loaded,
      is_view_readonly,
      dimension_general_dropdowns,
    } = storeToRefs(auto_accounting_store);

    const { highlightOption } = auto_accounting_store;

    const accounting_type_store = useAccountingTypeStore();
    const { view_template, view_types } = storeToRefs(accounting_type_store);
    return {
      highlightOption,
      view_types,
      view_template,
      is_view_readonly,
      dimension_dropdowns,
      dimension_general_dropdowns,
      accounts_loaded,
      dimension_rules,
      dimension_options: ref([] as dynamicObj[]),
      all_dimension_options: ref([] as dynamicObj[]),
      dimension_value: ref(''),
      input_value: ref(''),
    };
  },
});
</script>
<style scoped lang="scss"></style>
