<template>
  <q-icon v-if="showError" flat dense name="error" size="24px" color="red">
    <q-tooltip class="bg-red" anchor="bottom right" self="top right">
      {{ $t('field_required') }}
    </q-tooltip>
  </q-icon>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

export default defineComponent({
  mixins: [],
  props: {
    fieldName: {
      type: String,
      required: true,
    },
    additionalFieldError: {
      type: Array,
      required: true,
    },
  },
  computed: {
    showError() {
      return (
        Array.isArray(this.additionalFieldError) &&
        this.additionalFieldError.some(
          (error: any) => error.field === this.fieldName,
        )
      );
    },
  },
});
</script>
<style scoped lang="scss"></style>
