<template>
  <q-select
    class="fixed-q-select"
    tabindex="1"
    use-input
    fill-input
    hide-selected
    outlined
    dense
    v-model="localValue"
    :loading="!accounts_loaded"
    :options="filterAccounts"
    @input-value="selectInputValue"
    @filter="filterAccountsEvent"
    :readonly="isReadOnly()"
  >
    <template v-slot:selected-item="scope">
      <div class="ellipsis">{{ scope.opt.label }}</div>
    </template>

    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps">
        <q-item-section>
          <q-item-label v-if="scope.opt.parent === false" :class="'pl-20 '">
            <span v-html="highlightOption(scope.opt.label, input_value)"></span>
          </q-item-label>
          <q-item-label v-else>
            <span v-html="highlightOption(scope.opt.label, input_value)"></span>
          </q-item-label>
        </q-item-section>
      </q-item>
    </template>

    <template v-slot:append>
      <q-icon
        v-if="account_error !== ''"
        flat
        dense
        name="error"
        size="24px"
        color="red"
      >
        <q-tooltip class="bg-red" anchor="bottom right" self="top right">
          {{ account_error }}
        </q-tooltip>
      </q-icon>

      <q-icon
        flat
        dense
        size="24px"
        class="cursor-pointer"
        name="list"
        v-if="view_template === view_types.ln"
        @click.stop.prevent="openAccountDialog()"
      >
        <q-tooltip anchor="bottom right" self="top right">
          {{ $t('select_category_manually') }}
        </q-tooltip>
      </q-icon>
    </template>
    <q-tooltip v-if="localValue?.label">{{ localValue.label }}</q-tooltip>
  </q-select>

  <dialog-draggable
    v-model="display_accounts_dialog"
    full-width
    @keydown.esc="closeDialog"
    :title="$t('select_category_manually')"
    @onHide="closeDialog"
    :width="popup_width as any"
  >
    <q-card-section class="account-container">
      <div class="row full-width account-search-row q-mb-md back-white p-t-20">
        <q-input
          v-model="search_account"
          outlined
          dense
          class="col-12 search_account_input"
          :placeholder="
            $t('search') +
            ' (' +
            $t('after_typing_press_enter') +
            ')'
          "
          clearable
          @clear="clearManualAccountsSearch"
          @keyup.enter="searchAccounts"
        >
          <template v-slot:append>
            <q-icon name="search" @click="searchAccounts" />
          </template>
        </q-input>
      </div>

      <div class="grid account-categories">
        <template
          v-for="(account, index) in dialogFilteredAccounts"
          :key="index"
        >
          <div class="item">
            <div class="content">
              <DisplayAccounts
                @accountSelected="accountSelected"
                :nodes="account"
              ></DisplayAccounts>
            </div>
          </div>
        </template>
      </div>
    </q-card-section>
  </dialog-draggable>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import DisplayAccounts from './DisplayAccounts/category.vue';
import dialogDraggable from 'src/components/DialogDraggable.vue';
import { useAutoAccountingStore, useAccountingTypeStore } from 'src/store/main';
import helperUtil from 'src/utils/helperUtil';

export default defineComponent({
  mixins: [helperUtil],
  props: {
    item: {
      type: Object,
      required: true,
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    index: {
      type: Number,
      required: true,
    },
    child_index: {
      type: Number,
    },
  },
  components: {
    dialogDraggable,
    DisplayAccounts,
  },
  emits: ['update-account'],
  computed: {
    account_error: function (): string {
      return String(this.item.account_error);
    },
    show_auto_detect: function (): boolean {
      let display = false;
      if (this.hasTotalPredictions()) {
        display = true;
      }

      if (this.hasLineItemsPredictions()) {
        display = true;
      }

      return display;
    },
    localValue: {
      get() {
        return this.item.account as dynamicObj;
      },
      set(newValue: any) {
        this.$emit('update-account', { index: this.index, value: newValue });
      },
    },
  },
  mounted() {
    this.input_value = '';
    this.popup_width = this.calculateWidthForPopuup();
    window.addEventListener('resize', this.calculateWidthForPopuup);
    logInfo('Account component mounted');
  },
  unmounted: function () {
    window.removeEventListener('resize', this.calculateWidthForPopuup);
  },
  methods: {
    async init() {
      await this.$nextTick();
      this.searchInput = document!.querySelector(
        '.search_account_input',
      ) as HTMLInputElement;
      if (this.searchInput) {
        this.searchInput.focus();
      }
    },
    calculateWidthForPopuup() {
      let default_width = '800';

      const area_el = document.querySelector('.accounting-area') as HTMLElement;
      if (!area_el) {
        return default_width;
      }

      const calculated_width = area_el.offsetWidth - 300;
      if (calculated_width <= 0) {
        return default_width;
      }

      return String(calculated_width);
    },

    closeDialog() {
      this.dialogFilteredAccounts = this.categorized_accounts;
      this.display_accounts_dialog = false;
    },

    isReadOnly() {
      if (this.is_view_readonly) {
        return true;
      }

      if (this.item.readonly) {
        return true;
      }

      if (
        this.item.hasOwnProperty('split_items') &&
        this.item.split_items.length > 0
      ) {
        return true;
      }
      return false;
    },

    filterAccountsEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterAccounts = this.sortLettersThenNumbers(this.accounts);
        });
        return;
      }

      update(
        () => {
          this.filterAccounts = this.sortLettersThenNumbers(
            this.accountFilterByAnyValue(val),
          );
        },
        // KSB-36: Quasar clears its highlighted option on every menu update
        // unless the already selected account happens to survive the filter.
        // Without a highlighted option, Enter falls through to closeMenu(),
        // which restores the previous label — the filter is silently discarded.
        // Highlighting the first result makes Enter commit it, which is also
        // Quasar's own recipe for "filter and select the first option".
        this.highlightFirstFilteredAccount,
      );
    },

    highlightFirstFilteredAccount(select: any) {
      if (!select || select.options?.length === 0) {
        return;
      }

      // Reset first so a still-selected account cannot keep the highlight,
      // then move to the first selectable option without overwriting what the
      // user has typed so far.
      select.setOptionIndex(-1);
      select.moveOptionSelection(1, true);
    },

    searchAccounts() {
      if (!this.search_account || this.search_account.length === 0) {
        this.dialogFilteredAccounts = this.categorized_accounts;
        this.afterAccountsRendered();
        return;
      }

      const needle = this.search_account.toLowerCase();
      const filteredAccounts = this.accounts.filter(
        (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
      );

      this.dialogFilteredAccounts =
        this.getAccountAsCategories(filteredAccounts);
      this.afterAccountsRendered();
    },

    openAccountDialog() {
      this.search_account = '';
      this.display_accounts_dialog = true;
      this.init();
      this.afterAccountsRendered();
    },

    afterAccountsRendered() {
      setTimeout(() => {
        this.resizeAllGridItems();
      }, 0);
    },

    clearManualAccountsSearch() {
      this.search_account = '';
      this.dialogFilteredAccounts = this.categorized_accounts;
      this.afterAccountsRendered();
    },

    accountSelected(account: string) {
      const account_obj = this.accounts.filter(
        (v: any) => v.value.toLowerCase().indexOf(account) > -1,
      );

      if (account_obj.length > 0) {
        this.localValue = account_obj[0];
      }
      this.closeDialog();
    },

    resizeAllGridItems() {
      const allItems = document.getElementsByClassName('item');
      for (let x = 0; x < allItems.length; x++) {
        this.resizeGridItem(allItems[x]);
      }
    },
    resizeGridItem(item: any) {
      const grid = document.getElementsByClassName('grid')[0];
      if (!grid) {
        return;
      }
      const rowHeight = parseInt(
        window.getComputedStyle(grid).getPropertyValue('grid-auto-rows'),
      );
      const rowGap = parseInt(
        window.getComputedStyle(grid).getPropertyValue('grid-row-gap'),
      );
      const height = item.querySelector('.content').offsetHeight;
      const rowSpan = Math.ceil((height + rowGap) / (rowHeight + rowGap));
      item.style.gridRowEnd = 'span ' + rowSpan;
    },

    // Auto-Complete
    selectInputValue(value: any) {
      this.input_value = value;
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      categorized_accounts,
      accounts,
      accounts_loaded,
      is_view_readonly,
      accountFilterByAnyValue,
      total_line_predictions,
      line_items_line_predictions,
    } = storeToRefs(auto_accounting_store);

    const {
      hasTotalPredictions,
      hasLineItemsPredictions,
      getAccountAsCategories,
      highlightOption,
    } = auto_accounting_store;

    const filterAccounts: any = ref(auto_accounting_store.accounts);
    const dialogFilteredAccounts: any = ref(
      auto_accounting_store.categorized_accounts,
    );

    const accounting_type_store = useAccountingTypeStore();
    const { view_template, view_types } = storeToRefs(accounting_type_store);
    return {
      highlightOption,
      view_types,
      view_template,
      getAccountAsCategories,
      categorized_accounts,
      hasTotalPredictions,
      hasLineItemsPredictions,
      total_line_predictions,
      line_items_line_predictions,
      is_view_readonly,
      filterAccounts,
      dialogFilteredAccounts,
      accounts_loaded,
      accounts,
      accountFilterByAnyValue,
      display_accounts_dialog: ref(false),
      popup_width: ref('800'),
      search_account: ref(''),
      searchInput: ref({} as HTMLInputElement),
      input_value: ref(''),
    };
  },
});
</script>
