import jsonData from 'src/assets/voucher-text.json';

export default {
  methods: {
    getFieldLength(field_name: string): number | undefined {
      const fieldsConfig = jsonData['voucher_text'];

      if (!fieldsConfig || !fieldsConfig.validation_rules) {
        return undefined;
      }

      const maxLengthRule = fieldsConfig.validation_rules.find(
        (rule: any) => rule.rule === 'max_length',
      );

      if (!maxLengthRule) {
        return undefined;
      }

      return maxLengthRule.value;
    },
  },
};
