<template>
  <div class="row">
    <span
      class="secondary-c-text text-h6 mt-8 text-weight-bold only-for-approval"
    >
      <div class="text-capitalize full-width">{{ $t('auto_accounting') }}</div>
    </span>
  </div>
  <component
    v-if="view_template !== ''"
    :is="view_template"
    :currentView="view_template"
    :isMultiTaxSection="isMultiTaxSection"
    @addLineItem="addLineItem"
  >
  </component>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { uid } from 'quasar';
import { storeToRefs } from 'pinia';
import stringUtil from 'src/utils/string';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { auto_accounting_types_setting, CONSTANTS } from 'src/constants';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';

import {
  useAutoAccountingStore,
  useDocumentStore,
  useWebSocketStore,
  usePoMatchStore,
  useSettingStore,
  useAccountingTypeStore,
  useFormBuilderStore,
  usePOLineItemsStore,
  useFieldValuesSettingsStore,
  useUserStore,
} from 'src/store/main';

import { copyToClipboard } from 'quasar';
import LN_VIEW from './Detail/Templates/LN.vue';
import M3_VIEW from './Detail/Templates/M3.vue';
import helperMixin from 'src/mixins/helperMixin';
import { readOnlyDocStatus } from 'src/constants';
export default defineComponent({
  name: 'SectionAutoAccounting',
  el: '#app',
  mixins: [stringUtil, helperMixin],
  components: {
    LN_VIEW,
    M3_VIEW,
  },
  watch: {
    accounts_loaded: {
      handler: function (newVal, oldVal) {
        if (newVal && this.line_item_loaded) {
          this.loadMissingDimensions();
          this.doAccountPredictions();
        }
      },
    },
  },
  mounted() {
    this.init();
    // document.addEventListener('prepare_data', this.prepareDataEvent);

    document.addEventListener('prepare_data', (event: any) => {
      this.prepareDataEvent(event).catch(console.error);
    });
  },

  unmounted: function () {
    // document.removeEventListener('prepare_data', this.prepareDataEvent);
    document.addEventListener('prepare_data', (event: any) => {
      this.prepareDataEvent(event).catch(console.error);
    });
  },
  data() {
    return {
      auto_accounting_types_setting,
      line_item_columns: ['POSITION', 'DESCRIPTION', 'ITEM_NUMBER'],
      tax_code_list_names: [] as string[],
    };
  },
  methods: {
    async init() {
      try {
        (<any>window).acc = this;
        this.connect();
        this.docId = this.$route.params.id as string;
        this.doc_url = window.location.href;
        // SessionStorage.remove('doc_info');
        this.line_item_loaded = false;

        // await this.getDocumentById(this.docId);
        await this.getInvoiceDataByDocId(this.docId);

        this.setAccountingModeOptions();
        if (
          !this.record ||
          Object.keys(this.record).length === 0 ||
          this.record.success === false
        ) {
          return;
        }
        await this.startSettingsFetch();
        this.verifyUserSettings();
        this.handleReadOnlyView();
        this.setAccountingVariables();
        this.view_template = this.loadTemplateSettings();
        await this.prepareDataForView();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.accounting_error = msg;
      } finally {
        //this.processing = false;
        this.hideLoading();
      }
    },

    async getInvoiceDataByDocId(docId: string) {
      try {
        if (
          this.get_cached_data_id === docId &&
          (await this.setRecordFromCache())
        ) {
          return;
        }

        // this.showLoading();
        this.record = [];
        await this.getDocumentById(docId);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        // this.hideLoading();
      }
    },

    setAccountingModeOptions() {
      this.accounting_mode_options = [];
      this.accounting_mode_options.push({
        label: this.$t('split_by_total'),
        value: 'total_line',
      });

      if (!this.isPurchaseInvoice()) {
        this.accounting_mode_options.push({
          label: this.$t('line_items'),
          value: 'line_items',
        });
      }
    },

    verifyUserSettings() {
      this.setup_error = false;
      const errors_list = this.verifyModuleSettings();
      if (errors_list.length > 0) {
        this.setup_error = true;
        throw new Error(this.$t('missing_auto_accounting_settings'));
      }
    },

    // storageChangeEvent (e: any) {
    //   this.handleSessionStorageChange(e);
    // },

    // TODO::throw a warning before changing the template
    // async handleSessionStorageChange (e: any) {

    //   try {
    //     //
    //     this.handleStorageEvent(e);
    //     const template_view = this.loadTemplateSettings();
    //     if (template_view !== this.view_template) {
    //       // sync
    //       this.processing = true;
    //       this.view_template = template_view;
    //       await this.prepareDataForView();
    //     }
    //   } catch (err: any) {
    //     logError(err);
    //   } finally {
    //     this.processing = false;
    //   }

    // },

    handleReadOnlyView() {
      this.is_view_readonly = false;
      if (
        this.record.status == CONSTANTS.validated_pending_approval ||
        readOnlyDocStatus.includes(this.record.status)
      ) {
        this.is_view_readonly = true;
      }
    },

    loadTemplateSettings() {
      let template_name =
        this.user_settings[this.auto_accounting_types_setting];

      if (!template_name) {
        template_name = 'ln';
      }

      let view_template: string = this.view_types.ln;
      if (template_name === 'm3') {
        view_template = this.view_types.m3;
      }
      return view_template;
    },

    async prepareDataEvent(e: any) {
      this.showLoading();
      await this.prepareDataForView();
      this.hideLoading();
    },

    async prepareDataForView() {
      const isPOMatch = this.hasPoMatchData();
      await this.checkIfMultiTaxCode();

      // Every tax dropdown is rendered behind v-if="isMultiTaxSection", so there
      // is nothing to build for a document without multi tax sections.
      if (this.isMultiTaxSection) {
        if (this.view_template == this.view_types.m3) {
          await this.prepareM3TaxCodeDropdown();
        } else {
          this.prepareLNTaxCountryDropdown();
        }
      }

      this.lineItems = [];
      this.line_item_loaded = false;
      this.accounting_additional_fields = this.getAdditionalFields();
      this.setLineItemsObj();

      if (isPOMatch) {
        this.setPoTotalLineItem();
        await this.calculateMatchedTotal();
      }

      if (this.record.hasOwnProperty('accounting')) {
        this.loadSavedData();
        if (!isPOMatch) {
          this.lineItems = this.syncLineItemAmounts(
            this.amountFieldsList,
            this.lineItems,
          );
        }
      }

      if (!this.line_item_loaded) {
        this.prepareLineItems();
      }

      // this.addDummyData();
      if (this.accounts_loaded) {
        this.loadMissingDimensions();
        this.doAccountPredictions();
      }
      this.line_item_loaded = true;
    },

    prepareLineItems() {
      try {
        this.lineItems = [];
        if (this.hasPendingPoMatch()) {
          this.setPendingPoTotalLineItem();
          // for now only for one-to-one matching
          // this.disable_mode = true;
          if (this.is_multi_match) {
            this.disable_mode = true;
          } else {
            this.setPoMatchedLineItems();
            // prepare line items
          }
          return;
        }

        if (this.isMultiTaxSection) {
          this.prepareAmountsForMultiSection();
        } else {
          this.setTotallineItem();
        }
        this.setlineItems();
      } catch (err) {
        logError(err);
      }
    },

    async doAccountPredictions() {
      try {
        this.predictionsLoaded = false;

        if (!this.isValidData()) {
          logInfo('No Supplier for prediction', this.supplier_name);
          return;
        }

        const line_items = this.getLineItemsForPredictionAccount();
        if (line_items.length === 0) {
          return;
        }

        const data = {
          line_items: JSON.stringify(line_items),
          source_locale: this.amount_format_locale,
          doc_id: this.docId,
        };

        await this.getPredictions(data);
      } catch (err: any) {
        logError(err);
      } finally {
        this.predictionsLoaded = true;
      }
    },

    async setPoMatchedLineItems() {
      try {
        //
        if (
          !this.hasPoMatchData() ||
          this.record.po_items.length === 0 ||
          this.is_multi_match
        ) {
          return;
        }

        this.buildPoLinesObj(this.record.po_items);

        const lines = await this.getMatchedLines();
        if (lines.length === 0) {
          return;
        }

        for (const [index, item] of lines.entries()) {
          const line = this.baseLineItem();
          line.id = item.table_line_id;
          line.amount = item.amount;
          line.amount_standard = item.amount_standard;

          const table_line = this.lineDataObj[item.table_line_id];

          if (!table_line) {
            continue;
          }
          for (const column_name of this.line_item_columns) {
            if (table_line.columns.hasOwnProperty(column_name)) {
              line[column_name.toLowerCase()] =
                table_line.columns[column_name].formatted_value;
            }
          }

          this.lineItems.push(line);
        }
      } catch (err) {
        logError(err);
      }
    },

    setPendingPoTotalLineItem() {
      const line = this.getbaseTotalLineItem();
      line.amount = this.pending_amount;
      line.amount_standard = this.pending_amount_standard;
      this.lineItems.push(line);
    },

    hasPendingPoMatch() {
      try {
        let pendingAmount = parseFloat(
          this.pending_amount.replace(/[^0-9]/g, ''),
        );
        if (
          this.pending_amount &&
          this.pending_amount != '' &&
          pendingAmount > 0
        ) {
          return true;
        }
        return false;
      } catch (err) {
        logError(err);
        return true;
      }
    },

    loadSavedData() {
      // this.lineItems = this.record.accounting.line_items;
      const saved_line_items = this.record.accounting.line_items;
      this.accounting_mode = this.record.accounting.mode;
      this.line_item_loaded = false;

      if (this.hasPendingPoMatch()) {
        // for now only for one-to-one matching
        if (this.is_multi_match) {
          this.accounting_mode = 'total_line';
          this.disable_mode = true;
        } else {
          // prepare line items
        }
      }

      // add missing attributes in line items
      if (!Array.isArray(saved_line_items) || saved_line_items.length === 0) {
        return false;
      }

      const included_types = ['line_item', 'total_line_item'];

      for (const [index, item] of saved_line_items.entries()) {
        let new_line = this.baseLineItem();
        if (item.type === 'total_line_item') {
          new_line = this.getbaseTotalLineItem();
        }

        if (included_types.includes(item.type)) {
          this.line_item_loaded = true;
        }

        const final_item = Object.assign(new_line, item);

        if (item.split_items.length > 0) {
          for (const [
            split_index,
            splitted_item,
          ] of final_item.split_items.entries()) {
            let new_split_line = this.baseSplitLineItem();
            const final_split_item = Object.assign(
              new_split_line,
              splitted_item,
            );
            final_item.split_items[split_index] = final_split_item;
          }
        }

        this.lineItems.push(new_line);
      }
    },

    hasLineItems() {
      if (
        !this.record.tables ||
        this.record.tables.length == 0 ||
        !this.record.tables[0].hasOwnProperty('rows') ||
        this.record.tables[0].rows.length == 0
      ) {
        return false;
      }
      return true;
    },

    setlineItems() {
      if (!this.hasLineItems()) {
        return;
      }

      Array.from(this.record.tables[0].rows).forEach(
        (row: any, rowIndex: number) => {
          if (row.is_deleted === true || !row.id) {
            return;
          }

          const line = this.baseLineItem();
          line.id = row.id;

          const priority_amount_columns = new Map();
          priority_amount_columns.set('NET_AMOUNT', '');
          priority_amount_columns.set('TOTAL_AMOUNT', '');
          const standard_amounts = {} as dynamicObj;

          Array.from(row.columns).forEach((column: any, columnIndex: any) => {
            if (this.line_item_columns.includes(column.name)) {
              line[column.name.toLowerCase()] = column.formatted_value;
            }

            if (priority_amount_columns.has(column.name)) {
              priority_amount_columns.set(column.name, column.formatted_value);
              standard_amounts[column.name] = column.value;
            }
          });

          for (const [key, value] of priority_amount_columns.entries()) {
            if (value !== '') {
              line.amount = value;
              line.amount_standard = standard_amounts[key];
              break;
            }
          }

          this.lineItems.push(line);
        },
      );
    },

    setLineItemsObj() {
      if (!this.hasLineItems()) {
        return;
      }
      this.prepareTableLayoutObj();
      this.getTableColumns();
      let lineDataTemp = {} as dynamicObj;
      Array.from(this.record.tables[0].rows).forEach(
        (row: any, rowIndex: number) => {
          if (row.is_deleted === true || !row.id) {
            return;
          }

          lineDataTemp[row.id] = JSON.parse(JSON.stringify(row));
          lineDataTemp[row.id]['columns'] = [] as any;
          Array.from(row.columns).forEach((column: any, columnIndex: any) => {
            lineDataTemp[row.id].columns[column.name] = JSON.parse(
              JSON.stringify(column),
            );
          });
        },
      );

      Object.assign(this.lineDataObj, lineDataTemp);
    },

    setTotallineItem() {
      const line = this.getbaseTotalLineItem();

      if (
        this.record.fields &&
        Array.isArray(this.record.fields) &&
        this.record.fields.length > 0
      ) {
        this.record.fields.forEach((field: any, index: any) => {
          if (field.name !== 'total_net_amount') {
            return;
          }

          line.amount = field.formatted_value;
          line.amount_standard = field.value;
        });
      }

      this.lineItems.push(line);
    },

    addLineItem() {
      if (this.is_view_readonly) {
        return;
      }
      const line = this.baseLineItem();
      line.id = uid();
      this.lineItems.push(line);
    },

    setAccountingVariables() {
      // get
      this.amount_format_locale = this.doc_amount_format_locale;
      this.setSupplier();
    },

    setSupplier() {
      this.supplier_name = this.supplier;
      if (!this.isValidData()) {
        this.missing_supplier_warning = notify.warning(
          this.$t('missing_supplier_warning'),
        );
      }
    },

    emptyLineItems() {
      if (this.lineItems.length === 0) {
        this.empty_line_item = true;
      }
    },

    copyURL() {
      if (this.doc_url.trim().length > 0) {
        copyToClipboard(this.doc_url).then(() => {
          notify.success(this.$t('link_copied_to_clipboard'));
        });
      }
    },

    closeDialog(e: any) {
      this.empty_line_item = false;
    },

    addDummyData() {
      this.supplier_name = 'Fellow Consulting AG';
      // Array.from(this.lineItems).forEach((row: any, index: any) => {
      //   if (index === 1) {
      //     this.lineItems[index].amount = '85,00';
      //   }

      //   if (index === 2) {
      //     this.lineItems[index].amount = '180,00';
      //   }
      // });
    },

    async checkIfMultiTaxCode() {
      this.isMultiTaxSection = false;
      this.tax_code_list_names = [];
      this.taxCodeDropdown = [];

      const prams = {
        layout_type: '',
        doc_origin: this.record.doc_origin,
        doc_type: this.record.doc_type,
        sub_doc_type: this.record.sub_doc_type,
        include_layout_json: true,
        is_auto_accounting: true,
      };
      // load template to check if multisection
      await this.getLayoutTemplate(prams);
      this.checkMultiSections();
    },

    // LN only: the tax sections are referenced by position. M3 selects a tax
    // code straight from the list of values, see prepareM3TaxCodeDropdown().
    prepareLNTaxCountryDropdown() {
      this.taxCodeDropdown = [];

      for (let [index, item] of this.amountFieldsList.entries()) {
        let counter = index + 1;
        // prepare TaxCode And TaxCountry Dropdown
        this.taxCodeDropdown.push({
          value: counter,
          label:
            counter +
            ' ' +
            item.tax_country.formatted_value +
            ', ' +
            item.tax_code_without_country.formatted_value,
        });
      }
    },

    // Keys used to detect a change of the underlying document fields.
    // M3 has no tax country, so its lines only track tax code + net amount.
    buildLineItemFields(item: any) {
      const fields = [
        item.tax_code_without_country.orignal_name,
        item.net_amount.orignal_name,
      ];

      if (this.view_template != this.view_types.m3) {
        fields.push(item.tax_country.orignal_name);
      }

      return fields;
    },

    // Raw value so it can be matched against an option of taxCodeDropdown.
    // prepareAmountObject() uses 'empty' as its placeholder for a missing field.
    getExtractedTaxCode(item: any) {
      const tax_code = item.tax_code_without_country.value;
      return !tax_code || tax_code === 'empty' ? '' : String(tax_code);
    },

    prepareAmountsForMultiSection() {
      const line = this.getbaseTotalLineItem();

      for (let [index, item] of this.amountFieldsList.entries()) {
        const newItem = JSON.parse(JSON.stringify(line));

        newItem.amount = item.net_amount.formatted_value;
        newItem.amount_standard = item.net_amount.value;

        let counter = index + 1;
        newItem.position = counter;
        if (this.view_template == this.view_types.m3) {
          newItem.tax_code = this.getExtractedTaxCode(item);
        }

        // this key will be used to identify the change of the fields
        newItem.fields = this.buildLineItemFields(item);

        this.lineItems.push(newItem);
      }
    },

    checkMultiSections() {
      if (!this.layout || this.layout.length == 0) {
        return;
      }

      this.amountFieldsList = [];
      let data: any = {};
      const recordFields = Array.isArray(this.record?.fields)
        ? this.record.fields
        : [];
      recordFields.forEach((value: any) => {
        data[value.name] = value;
      });

      for (const [index, group] of this.layout.entries()) {
        const rows = Array.isArray(group?.rows) ? group.rows : [];
        for (let [itemIndex, fieldDef] of rows.entries()) {
          if (fieldDef.fieldType != formBuilderInputTypes.SUB_GROUP) {
            // if net amounts and not multi tax code section, then also prepare the list to detect the change in the list
            if (fieldDef.name && fieldDef.name.startsWith('net_amount')) {
              // we only need net amount fields as for non multi tax case only those fields are used
              this.prepareAmountObject(data, '', fieldDef.name, '');
            }
            continue;
          }

          this.isMultiTaxSection = true;

          // let firstChildName = fieldDef.rows[0].name ? fieldDef.rows[0].name : fieldDef.rows[0].field_name;
          const childRows = Array.isArray(fieldDef.rows) ? fieldDef.rows : [];
          const taxCodeField = this.findFieldStartingWith(
            childRows,
            'tax_code_without_country',
          );
          let taxCodeKey = taxCodeField ? String(taxCodeField.field_name) : '';
          let netAmountKey = this.findKeyStartingWith(childRows, 'net_amount') || '';
          let taxCountryKey = this.findKeyStartingWith(childRows, 'tax_country') || '';

          if (!netAmountKey) {
            continue;
          }

          this.collectTaxCodeListName(taxCodeField);

          this.prepareAmountsData(
            data,
            taxCodeKey,
            netAmountKey,
            taxCountryKey,
          );
        }
      }
    },
    prepareAmountsData(
      data: any,
      taxCodeKey: string,
      netAmountKey: string,
      taxCountryKey: string,
    ) {
      let subGroupChildFields = this.findSubGroupChildFields(netAmountKey);

      this.prepareAmountObject(data, taxCodeKey, netAmountKey, taxCountryKey);

      if (subGroupChildFields && Object.keys(subGroupChildFields).length == 0) {
        return;
      }
      for (let item of subGroupChildFields) {
        this.prepareAmountObject(data, taxCodeKey, item.name, taxCountryKey);
      }
    },
    prepareAmountObject(
      data: any,
      taxCodeKey: string,
      netAmountKey: string,
      taxCountryKey: string,
    ) {
      if (!data[netAmountKey] || !data[netAmountKey].formatted_value) {
        return;
      }
      const postFix = this.getItemPostFix(netAmountKey);

      taxCodeKey = taxCodeKey + postFix;
      // netAmountKey = netAmountKey + postFix;
      taxCountryKey = taxCountryKey + postFix;

      const item = {
        tax_code_without_country: {
          orignal_name: taxCodeKey,
          value:
            data[taxCodeKey] && data[taxCodeKey].value
              ? data[taxCodeKey].value
              : 'empty',
          formatted_value:
            data[taxCodeKey] && data[taxCodeKey].formatted_value
              ? data[taxCodeKey].formatted_value
              : 'empty',
        },

        net_amount: {
          orignal_name: netAmountKey,
          value:
            data[netAmountKey] && data[netAmountKey].value
              ? data[netAmountKey].value
              : 0,
          formatted_value:
            data[netAmountKey] && data[netAmountKey].formatted_value
              ? data[netAmountKey].formatted_value
              : 0,
        },

        tax_country: {
          orignal_name: taxCountryKey,
          value:
            data[taxCountryKey] && data[taxCountryKey].value
              ? data[taxCountryKey].value
              : 'empty',
          formatted_value:
            data[taxCountryKey] && data[taxCountryKey].formatted_value
              ? data[taxCountryKey].formatted_value
              : 'empty',
        },
      };

      this.amountFieldsList.push(item);
    },
    findFieldStartingWith(data: any, prefix: string) {
      return data.find((obj: any) => obj.field_name.startsWith(prefix));
    },
    findKeyStartingWith(data: any, prefix: string) {
      const item: any = this.findFieldStartingWith(data, prefix);
      return item ? String(item.field_name) : '';
    },

    // Each multi tax sub group configures its own list of values on the tax code
    // field (Steuercode_voll, Steuercode_Reduziert, Steuercode_Frei, ...).
    collectTaxCodeListName(taxCodeField: any) {
      if (!taxCodeField || !taxCodeField.list_of_values) {
        return;
      }

      const list_name = String(taxCodeField.list_of_values).trim();
      if (!list_name || this.tax_code_list_names.includes(list_name)) {
        return;
      }

      this.tax_code_list_names.push(list_name);
    },

    // Loads every list collected above and merges them into a single deduped
    // dropdown for the M3 multi tax header. Falls back to the tax codes read off
    // the document when no list of values is configured.
    async prepareM3TaxCodeDropdown() {
      this.taxCodeDropdown = [];

      try {
        for (const list_name of this.tax_code_list_names) {
          this.addNameToLovList(list_name);
        }

        if (this.tax_code_list_names.length > 0) {
          await this.populateListsAndValues();
        }

        const sub_org_id = await this.getSubOrgId();
        const seen = new Set<string>();

        for (const list_name of this.tax_code_list_names) {
          for (const option of this.getListOfValuesAsSelectList(list_name)) {
            const value = String(option.value ?? '').replace(/\u200B/g, '');
            if (!value || seen.has(value)) {
              continue;
            }

            // Values without a sub organisation are global, the rest belong to
            // the sub organisation the user is working in.
            if (option.sub_org_id && option.sub_org_id != sub_org_id) {
              continue;
            }

            seen.add(value);
            this.taxCodeDropdown.push({
              value,
              label: option.label ? String(option.label) : value,
            });
          }
        }
      } catch (err) {
        logError(err);
      }

      if (this.taxCodeDropdown.length === 0) {
        this.setExtractedTaxCodesAsDropdown();
      }
    },

    setExtractedTaxCodesAsDropdown() {
      const seen = new Set<string>();

      for (const item of this.amountFieldsList) {
        // Same source as the seeded line.tax_code, otherwise nothing preselects.
        const value = this.getExtractedTaxCode(item);
        if (!value || seen.has(value)) {
          continue;
        }

        seen.add(value);
        this.taxCodeDropdown.push({ value, label: value });
      }
    },
    getItemPostFix(itemName: string) {
      let postFix = '';

      if (itemName.includes('__')) {
        const endingString = this.getStringLastPart(itemName, '__');
        postFix = '__' + endingString;
      }
      return postFix;
    },
    syncLineItemAmounts(newData: any, savedData: any): any {
      // STEP 1: Build a Set of all current net_amount orignal_names from newData
      const currentFieldSet = new Set(
        newData.map((item: any) => item.net_amount.orignal_name as string),
      );

       
      const totalLineItems = savedData.filter(
        (item: any) =>
          item.type === 'total_line_item' &&
          item.fields &&
          item.fields.length > 0,
      );

      if (!totalLineItems || totalLineItems.length == 0) {
        return savedData;
      }

      const lineItems = savedData.filter(
        (item: any) => item.type !== 'total_line_item',
      );

      // STEP 2: Update existing or Add new
      newData.forEach((currentItem: any) => {
        const fieldName = currentItem.net_amount.orignal_name;
        const formattedValue = currentItem.net_amount.formatted_value;

        let matchedLine = totalLineItems.find(
          (item: any) =>
             
            item.fields && item.fields.includes(fieldName),
        );

        if (matchedLine) {
          let dataChanged = false;

          // If the amount is different, update it
          if (matchedLine.amount !== formattedValue) {
            matchedLine.amount = formattedValue;
            matchedLine.amount_standard = parseFloat(
              currentItem.net_amount.value,
            );
            dataChanged = true;
          }

          // Only seed the tax code, never overwrite it: the M3 multi tax header
          // lets the user pick one from the list of values and that choice has
          // to survive a reload.
          if (
            this.view_template == this.view_types.m3 &&
            !matchedLine.tax_code
          ) {
            matchedLine.tax_code = this.getExtractedTaxCode(currentItem);
          }

          if (dataChanged && matchedLine.split_items) {
            // empty split amount data and trigger calculate
            for (const [index, item] of matchedLine.split_items.entries()) {
              item.amount = '';
              item.amount_standard = 0;
              item.percentage = '';
              item.percent_float = '';
            }
          }
        } else {
          // Add new line if it doesn't exist
          const newLine = this.getbaseTotalLineItem();
          newLine.amount = formattedValue;
          newLine.amount_standard = parseFloat(currentItem.net_amount.value);
          newLine.position = totalLineItems.length + 1;

          newLine.fields = this.buildLineItemFields(currentItem);

          // Optional: handle view_template-specific logic for new line
          if (this.view_template == this.view_types.m3) {
            newLine.tax_code = this.getExtractedTaxCode(currentItem);
          }

          totalLineItems.push(newLine);
        }
      });

      // STEP 3: Remove any totalLineItems rows that don't exist in newData
      const filteredTotalLineItems = totalLineItems.filter(
        (item: any) =>
           
          item.fields && item.fields.some((f: any) => currentFieldSet.has(f)),
      );

       
      return [...filteredTotalLineItems, ...lineItems];
    },
  },
