<template>
  <div
    class="accounting-fields-container"
    :id="lineItems[index].id"
    :data-id="lineItems[index].id"
  >
    <div class="width-40 text-align-center p-4 p-t-10">
      <span v-if="lineItems[index].hasOwnProperty('position')">
        {{ lineItems[index].position }}
      </span>
    </div>

    <div class="flex-1">
      <div class="row">
        <div
          class="p-4"
          :class="isMultiTaxSection ? 'primary-field' : 'primary-three-field'"
        >
          <Account
            :readonly="lineItems[index].readonly"
            v-on:update-account="updateAccount"
            :item="lineItems[index]"
            :index="index"
          />
        </div>
        <div
          class="p-4"
          :class="isMultiTaxSection ? 'primary-field' : 'primary-three-field'"
        >
          <q-input
            outlined
            dense
            tabindex="1"
            v-model="lineItems[index].voucher_text"
            :readonly="
              lineItems[index].split_items.length > 0 || is_view_readonly
            "
            :maxlength="getFieldLength('voucher_text')"
          >
            <template v-slot:append>
              <ErrorIcon
                :fieldName="'voucher_text'"
                :additionalFieldError="additional_field_error"
              />
            </template>
            <div
              class="char-counter"
              v-if="
                lineItems[index].voucher_text && getFieldLength('voucher_text')
              "
            >
              {{ lineItems[index].voucher_text.length }} /
              {{ getFieldLength('voucher_text') }}
            </div>
          </q-input>
        </div>

        <div
          :class="isMultiTaxSection ? 'secondary-field' : 'primary-three-field'"
        >
          <div class="row">
            <div v-if="isMultiTaxSection" class="col-5 p-4">
              <q-select
                tabindex="1"
                class="ellipsify"
                emit-value
                map-options
                outlined
                dense
                v-model="lineItems[index].tax_code"
                :options="taxCodeDropdown as any"
                :readonly="
                  lineItems[index].split_items.length > 0 || is_view_readonly
                "
              >
              </q-select>
            </div>
            <div class="p-4" :class="isMultiTaxSection ? 'col-7' : 'col-12'">
              <Amount :index="index" />
            </div>
          </div>
        </div>
      </div>
    </div>

    <div v-if="!is_view_readonly" class="w-75px p-4 p-t-10">
      <SplitLineItemBtn :index="index" />
      <UnSplitLineItemBtn :index="index" />
      <AddChildLineItem :index="index" />
    </div>
  </div>

  <div class="row">
    <div class="width-40"></div>

    <div class="flex-1">
      <Dimensions :index="index" />
    </div>
    <div v-if="!is_view_readonly" class="w-75px"></div>
  </div>

  <div class="total-line-item-area full-width">
    <SplitedLineItems :index="index" />
  </div>

  <div class="row q-pt-sm" v-if="lineItems[index].split_items.length > 0">
    <div class="width-40"></div>

    <div class="flex-1">
      <div class="row">
        <div class="primary-field p-4"></div>
        <div class="primary-field p-4"></div>
        <div class="secondary-field p-4">
          <span class="q-mr-md"> {{ $t('unsettled_amount') }}: </span>
          <span
            style="margin-left: 12px"
            v-if="lineItems[index].hasOwnProperty('pending_amount')"
          >
            {{ lineItems[index].pending_amount }}
          </span>
          <q-icon
            v-if="lineItems[index].error !== ''"
            flat
            dense
            name="error"
            size="20px"
            color="red"
            class="q-ml-sm"
          >
            <q-tooltip class="bg-red" anchor="bottom right" self="top right">
              {{ lineItems[index].error }}
            </q-tooltip>
          </q-icon>
        </div>
      </div>
    </div>
    <div v-if="!is_view_readonly" class="w-75px"></div>
  </div>
</template>

<script lang="ts">
const path = 'src/pages/AutoAccounting/Detail';

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useAutoAccountingStore } from 'src/store/main';
import validationHelper from 'src/utils/validationHelper';
import Amount from 'src/pages/AutoAccounting/Detail/lineItem/Amount.vue';
import Account from 'src/pages/AutoAccounting/Detail/components/Account.vue';
import ErrorIcon from 'src/pages/AutoAccounting/Detail/components/ErrorIcon.vue';
import Dimensions from 'src/pages/AutoAccounting/Detail/lineItem/Dimensions.vue';
import AddChildLineItem from 'src/pages/AutoAccounting/Detail/lineItem/AddChildLineItem.vue';
import SplitLineItemBtn from 'src/pages/AutoAccounting/Detail/lineItem/SplitLineItemBtn.vue';
import UnSplitLineItemBtn from 'src/pages/AutoAccounting/Detail/lineItem/UnSplitLineItemBtn.vue';
import SplitedLineItems from 'src/pages/AutoAccounting/Detail/Templates/M3/SplitedLineItems.vue';

export default defineComponent({
  mixins: [validationHelper],
  props: {
    index: {
      type: Number,
      required: true,
    },
    additional_field_error: {
      type: Array,
      default: () => [],
    },
  },
  components: {
    SplitedLineItems,
    Dimensions,
    Amount,
    Account,
    AddChildLineItem,
    SplitLineItemBtn,
    UnSplitLineItemBtn,
    ErrorIcon,
  },
  methods: {
    updateAccount(newValue: any) {
      if (this.is_view_readonly) {
        return;
      }

      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      this.updateAccountInStore(this.index, null, newValue.value);
    },

    updateAmount(newValue: any) {
      if (this.is_view_readonly || this.index === null) {
        return;
      }

      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      this.lineItems[this.index].amount = newValue.value;
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      lineItems,
      is_view_readonly,
      isMultiTaxSection,
      taxCodeDropdown,
    } = storeToRefs(auto_accounting_store);
    const {
      getDimensionsForAccount,
      validateLine,
      updateAccount: updateAccountInStore,
    } = auto_accounting_store;
    return {
      lineItems,
      is_view_readonly,
      isMultiTaxSection,
      taxCodeDropdown,
      validateLine,
      updateAccountInStore,
      getDimensionsForAccount,
    };
  },
});
</script>
<style scoped lang="scss"></style>
