<!--vbase-->
<template>
  <div class="line-item-container ml-16 q-mr-sm">
    <div class="lineItems">
      <div class="accounting-fields-container accounting-table-header">
        <div class="width-40 p-4">Pos</div>
        <div class="flex-1">
          <div class="row">
            <div
              class="p-4"
              :class="
                isMultiTaxSection ? 'primary-field' : 'primary-three-field'
              "
            >
              {{ $t('accounts') }}
            </div>
            <div
              class="p-4"
              :class="
                isMultiTaxSection ? 'primary-field' : 'primary-three-field'
              "
            >
              {{ $t('voucher_text') }}
            </div>
            <div
              class="p-4"
              :class="
                isMultiTaxSection ? 'secondary-field' : 'primary-three-field'
              "
            >
              <div class="row">
                <div v-if="isMultiTaxSection" class="col-5 p-4">
                  {{ $t('tax_code') }}
                </div>
                <div
                  class="p-4"
                  :class="isMultiTaxSection ? 'col-7' : 'col-12'"
                >
                  {{ $t('amount_title') }}
                </div>
              </div>
            </div>
          </div>
        </div>
        <div v-if="!is_view_readonly" class="w-75px p-4"></div>
      </div>

      <template v-if="line_item_loaded">
        <div class="accounting-fields-area q-mb-md">
          <template v-if="isMultiTaxSection">
            <template v-if="accounting_mode != 'line_items'">
              <template v-for="(item, index) in lineItems" :key="item">
                <template v-if="item.type == 'total_line_item'">
                  <MuLtiTaxSection
                    :index="index"
                    :additional_field_error="
                      lineItems[index].additional_field_error
                    "
                  />
                </template>
              </template>
            </template>
          </template>

          <TotalLineItem
            :additional_field_error="lineItems[0].additional_field_error"
            v-else
          />
        </div>

        <template v-if="accounting_mode === 'line_items'">
          <template v-for="(item, index) in lineItems" :key="item">
            <template v-if="item.type === 'line_item'">
              <lineItem
                :index="index"
                :additional_field_error="
                  lineItems[index].additional_field_error
                "
              />
              <q-separator class="q-mt-sm" />
            </template>
          </template>
          <div class="row q-mt-sm">
            <div class="width-40 p-4">
              <q-icon
                name="add"
                size="22px"
                @click="addLineItem()"
                @keydown.enter="addLineItem()"
                tabindex="1"
                class="cursor-pointer add-icon-xs"
                :class="is_view_readonly ? 'disabled' : ''"
              >
                <q-tooltip>{{ $t('add_new_line_item') }}</q-tooltip>
              </q-icon>
            </div>
            <div class="flex-1"></div>
          </div>
        </template>
      </template>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import stringUtil from 'src/utils/string';
import { defineComponent, ref } from 'vue';
import helperMixin from 'src/mixins/helperMixin';
import { isEmptyString } from 'src/utils/general';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { useAccountingTypeStore, useAutoAccountingStore } from 'src/store/main';
import lineItem from 'src/pages/AutoAccounting/Detail/Templates/M3/lineItem.vue';
import TotalLineItem from 'src/pages/AutoAccounting/Detail/Templates/M3/TotalLineItem.vue';
import MuLtiTaxSection from 'src/pages/AutoAccounting/Detail/Templates/M3/MuLtiTaxSection.vue';
export default defineComponent({
  el: '#app',
  mixins: [stringUtil, helperMixin],
  components: {
    lineItem,
    TotalLineItem,
    MuLtiTaxSection,
  },
  watch: {},
  emits: ['addLineItem'],
  props: {
    isMultiTaxSection: {
      type: Boolean,
      default: false,
    },
  },
  mounted() {
    this.init();

    document.addEventListener('reload_accounts', () => {
      this.reloadAccounts();
    });
  },

  unmounted: function () {
    document.removeEventListener('reload_accounts', () => {
      this.reloadAccounts();
    });
  },
  data() {
    return {};
  },
  methods: {
    async init() {
      try {
        if (!isEmptyString(this.accounting_error)) {
          return;
        }
        await this.fetchM3AccountsPromise();
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        this.accounting_error = msg;
      }
    },

    addLineItem() {
      // trigger event
      this.$emit('addLineItem');
    },
    async reloadAccounts() {
      await this.reloadM3Accounts();
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      accounts,
      lineItems,
      dimensions,
      accounting_mode,
      accounts_loaded,
      dimension_rules,
      is_view_readonly,
      accounting_error,
      dimension_dropdowns,
      dimension_general_dropdowns,
    } = storeToRefs(auto_accounting_store);

    const { fetchM3AccountsPromise, reloadM3Accounts } = auto_accounting_store;

    const accounting_type_store = useAccountingTypeStore();
    const { line_item_loaded } = storeToRefs(accounting_type_store);

    return {
      fetchM3AccountsPromise,
      reloadM3Accounts,
      accounts,
      lineItems,
      dimensions,
      dimension_rules,
      accounts_loaded,
      accounting_mode,
      is_view_readonly,
      accounting_error,
      line_item_loaded,
      dimension_dropdowns,
      dimension_general_dropdowns,
      fab1: ref(false),
    };
  },
});
</script>
