<template>
  <template v-if="header_index !== null">
    <div
      class="accounting-fields-container"
      :id="lineItems[header_index].id"
      :data-id="lineItems[header_index].id"
    >
      <div class="width-40 text-align-center p-4 p-t-10">
        {{ $t('total') }}
      </div>

      <div class="flex-1">
        <div class="row">
          <div class="primary-three-field p-4">
            <Account
              :readonly="lineItems[header_index].readonly"
              v-on:update-account="updateAccount"
              :item="lineItems[header_index]"
              :index="header_index"
            />
          </div>
          <div class="primary-three-field p-4">
            <q-input
              class="full-width"
              tabindex="1"
              outlined
              dense
              v-model="lineItems[header_index].voucher_text"
              :readonly="
                lineItems[header_index].split_items.length > 0 ||
                lineItems[header_index].readonly ||
                is_view_readonly
              "
              :maxlength="getFieldLength('voucher_text')"
            >
              <template v-slot:append>
                <ErrorIcon
                  :fieldName="'voucher_text'"
                  :additionalFieldError="additional_field_error"
                />
                <div
                  class="char-counter"
                  v-if="
                    lineItems[header_index].voucher_text &&
                    getFieldLength('voucher_text')
                  "
                >
                  {{ lineItems[header_index].voucher_text.length }} /
                  {{ getFieldLength('voucher_text') }}
                </div>
              </template>
            </q-input>
          </div>
          <div class="primary-three-field p-4">
            <Amount :index="header_index" />
          </div>
        </div>
      </div>

      <div v-if="!is_view_readonly" class="w-75px p-4 p-t-10">
        <SplitLineItemBtn :index="header_index" />
        <UnSplitLineItemBtn :index="header_index" />
        <AddChildLineItem :index="header_index" />
      </div>
    </div>

    <div class="row">
      <div class="width-40"></div>

      <div class="flex-1">
        <Dimensions :index="header_index" />
      </div>
      <div v-if="!is_view_readonly" class="w-75px"></div>
    </div>

    <div class="total-line-item-area full-width">
      <SplitedLineItems :index="header_index" />
    </div>

    <div
      class="row q-mt-md accounting-fields-area back-white"
      :class="{ 'display-none': is_view_readonly }"
    >
      <div class="width-40"></div>
      <div class="flex-1">
        <div class="row">
          <div class="primary-three-field p-8"></div>
          <div class="primary-three-field p-8">
            <span class="q-mr-md"> {{ $t('recorded_bookings') }}: </span>
            <span
              style="margin-left: 12px"
              v-if="
                lineItems[header_index].hasOwnProperty('lines_total_amount')
              "
            >
              {{ lineItems[header_index].lines_total_amount }}
            </span>
          </div>
          <div class="primary-three-field p-8">
            <span class="q-mr-md"> {{ $t('unsettled_amount') }}: </span>
            <span
              style="margin-left: 12px"
              v-if="lineItems[header_index].hasOwnProperty('pending_amount')"
            >
              {{ lineItems[header_index].pending_amount }}
            </span>
            <q-icon
              v-if="lineItems[header_index].error !== ''"
              flat
              dense
              name="error"
              size="20px"
              color="red"
              class="q-ml-sm"
            >
              <q-tooltip class="bg-red" anchor="bottom right" self="top right">
                {{ lineItems[header_index].error }}
              </q-tooltip>
            </q-icon>
          </div>
        </div>
      </div>
      <div v-if="!is_view_readonly" class="w-75px"></div>
    </div>
  </template>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useAutoAccountingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

import SplitedLineItems from 'src/pages/AutoAccounting/Detail/Templates/M3/SplitedLineItems.vue';
import Dimensions from 'src/pages/AutoAccounting/Detail/lineItem/Dimensions.vue';
import Amount from 'src/pages/AutoAccounting/Detail/lineItem/Amount.vue';
import Account from 'src/pages/AutoAccounting/Detail/components/Account.vue';
import AddChildLineItem from 'src/pages/AutoAccounting/Detail/lineItem/AddChildLineItem.vue';
import SplitLineItemBtn from 'src/pages/AutoAccounting/Detail/lineItem/SplitLineItemBtn.vue';
import UnSplitLineItemBtn from 'src/pages/AutoAccounting/Detail/lineItem/UnSplitLineItemBtn.vue';
import validationHelper from 'src/utils/validationHelper';
import ErrorIcon from 'src/pages/AutoAccounting/Detail/components/ErrorIcon.vue';

export default defineComponent({
  mixins: [validationHelper],
  props: {
    additional_field_error: {
      type: Array,
      default: () => [],
    },
  },
  components: {
    SplitedLineItems,
    Dimensions,
    Amount,
    Account,
    AddChildLineItem,
    SplitLineItemBtn,
    UnSplitLineItemBtn,
    ErrorIcon,
  },
  mounted() {
    this.header_index = this.getTotalLineIndex();
  },
  methods: {
    updateAccount(newValue: any) {
      if (this.is_view_readonly || this.header_index === null) {
        return;
      }

      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      this.lineItems[this.header_index].account = newValue.value;
      this.lineItems[this.header_index].account_error = '';

      this.updateAccountInStore(this.header_index, null, newValue.value);
    },

    updateAmount(newValue: any) {
      if (this.is_view_readonly || this.header_index === null) {
        return;
      }

      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      this.lineItems[this.header_index].amount = newValue.value;
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const { lineItems, getTotalLineIndex, is_view_readonly } = storeToRefs(
      auto_accounting_store,
    );
    const {
      getDimensionsForAccount,
      validateLine,
      updateAccount: updateAccountInStore,
    } = auto_accounting_store;
    return {
      validateLine,
      updateAccountInStore,
      getDimensionsForAccount,
      is_view_readonly,
      getTotalLineIndex,
      lineItems,
      header_index: ref(null as null | number),
    };
  },
});
</script>
<style scoped lang="scss"></style>
