<template>
  <template v-if="header_index !== null">
    <div
      class="accounting-fields-container"
      :id="lineItems[header_index].id"
      :data-id="lineItems[header_index].id"
    >
      <div class="width-40 text-align-center p-4 p-t-10">
        {{ $t('total') }}
      </div>

      <div class="flex-1">
        <div class="row">
          <div class="primary-three-field p-4">
            <Account
              :readonly="lineItems[header_index].readonly"
              v-on:update-account="updateAccount"
              :item="lineItems[header_index]"
              :index="header_index"
            />
          </div>
          <div class="primary-three-field p-4">
            <q-input
              class="full-width"
              tabindex="1"
              outlined
              dense
              v-model="lineItems[header_index].booking_reference"
              :readonly="
                lineItems[header_index].split_items.length > 0 ||
                is_view_readonly
              "
              maxlength="30"
            >
              <template v-slot:append>
                <q-icon
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                  v-if="false"
                >
                  <q-tooltip
                    class="bg-red"
                    anchor="bottom right"
                    self="top right"
                  >
                    {{ $t('field_required') }}
                  </q-tooltip>
                </q-icon>
                <div
                  class="char-counter"
                  v-if="lineItems[header_index].booking_reference"
                >
                  {{ lineItems[header_index].booking_reference.length }} / 30
                </div>
              </template>
            </q-input>
            <q-tooltip v-if="lineItems[header_index].booking_reference">{{
              lineItems[header_index].booking_reference
            }}</q-tooltip>
          </div>
          <div class="primary-three-field p-4">
            <Amount :index="header_index" />
          </div>
        </div>
      </div>

      <div v-if="!is_view_readonly" class="w-75px p-4 p-t-10">
        <SplitLineItemBtn :index="header_index" />
        <UnSplitLineItemBtn :index="header_index" />
        <AddChildLineItem :index="header_index" />
      </div>
    </div>

    <div class="row">
      <div class="width-40"></div>

      <div class="flex-1">
        <Dimensions :index="header_index" />
      </div>
      <div v-if="!is_view_readonly" class="w-75px"></div>
    </div>

    <div v-if="false && hasAdditionalFields()" class="primary-three-field p-4">
      <div
        v-for="(field, index) in accounting_additional_fields"
        :key="index"
        :style="dynamicAdditionalFieldStyle as any"
      >
        <q-input
          v-if="lineItems[header_index].hasOwnProperty(field.field_name)"
          class="full-width"
          outlined
          dense
          v-model="lineItems[header_index][field.field_name]"
          :readonly="
            lineItems[header_index].split_items.length > 0 || is_view_readonly
          "
          :counter="!!getFieldMaxLength(field.field_name)"
          :maxlength="getFieldMaxLength(field.field_name)"
        >
          <template v-slot:append>
            <q-icon
              v-if="showErrorIcon(field.field_name, additional_field_error)"
              flat
              dense
              name="error"
              size="24px"
              color="red"
            >
              <q-tooltip class="bg-red" anchor="bottom right" self="top right">
                {{ $t('field_required') }}
              </q-tooltip>
            </q-icon>
          </template>
        </q-input>
        <q-tooltip>{{ lineItems[header_index][field.field_name] }}</q-tooltip>
      </div>
    </div>

    <div class="total-line-item-area full-width">
      <SplitedLineItems
        :index="header_index"
        :additional_field_error="lineItems[header_index].split_items"
      />
    </div>

    <div
      class="row q-mt-md accounting-fields-area back-white height-33"
      :class="{ 'display-none': is_view_readonly }"
      v-if="lineItems[header_index].split_items.length > 0"
    >
      <div class="width-40"></div>

      <div class="flex-1">
        <div class="row">
          <div class="primary-three-field p-4"></div>
          <div class="primary-three-field p-4"></div>
          <div class="primary-three-field p-4">
            <span class="q-mr-md"> {{ $t('unsettled_amount') }}: </span>
            <span
              style="margin-left: 12px"
              v-if="lineItems[header_index].hasOwnProperty('pending_amount')"
            >
              {{ lineItems[header_index].pending_amount }}
            </span>
            <q-icon
              v-if="lineItems[header_index].error !== ''"
              flat
              dense
              name="error"
              size="20px"
              color="red"
              class="q-ml-sm"
            >
              <q-tooltip class="bg-red" anchor="bottom right" self="top right">
                {{ lineItems[header_index].error }}
              </q-tooltip>
            </q-icon>
          </div>
        </div>
      </div>
      <div v-if="!is_view_readonly" class="w-75px"></div>
    </div>
  </template>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import Amount from 'src/pages/AutoAccounting/Detail/lineItem/Amount.vue';
import Account from 'src/pages/AutoAccounting/Detail/components/Account.vue';
import Dimensions from 'src/pages/AutoAccounting/Detail/lineItem/Dimensions.vue';
import AddChildLineItem from 'src/pages/AutoAccounting/Detail/lineItem/AddChildLineItem.vue';
import SplitLineItemBtn from 'src/pages/AutoAccounting/Detail/lineItem/SplitLineItemBtn.vue';
import {
  useAccountingTypeStore,
  useAutoAccountingStore,
  useSettingStore,
} from 'src/store/main';
import SplitedLineItems from 'src/pages/AutoAccounting/Detail/Templates/LN/SplitedLineItems.vue';
import UnSplitLineItemBtn from 'src/pages/AutoAccounting/Detail/lineItem/UnSplitLineItemBtn.vue';
import cache from 'src/utils/cache';

export default defineComponent({
  mixins: [cache],
  props: {
    additional_field_error: {
      type: Array,
      default: () => [],
    },
  },
  components: {
    Amount,
    Account,
    Dimensions,
    SplitedLineItems,
    AddChildLineItem,
    SplitLineItemBtn,
    UnSplitLineItemBtn,
  },
  mounted() {
    this.header_index = this.getTotalLineIndex();
  },
  methods: {
    updateAccount(newValue: any) {
      if (this.is_view_readonly || this.header_index === null) {
        return;
      }

      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      this.lineItems[this.header_index].account = newValue.value;
      this.lineItems[this.header_index].account_error = '';

      this.updateAccountInStore(this.header_index, null, newValue.value);
    },

    updateAmount(newValue: any) {
      if (this.is_view_readonly || this.header_index === null) {
        return;
      }

      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      this.lineItems[this.header_index].amount = newValue.value;
    },

    getFieldMaxLength(field_name: string) {
      const valid_booking_reference = this.user_settings[
        'AUTO_ACCOUNTING_FIELDS'
      ] as string;
      const fieldsConfig = JSON.parse(valid_booking_reference);

      const fieldConfig = fieldsConfig.find(
        (fieldConfig: any) => fieldConfig.field_name === field_name,
      );
      if (!fieldConfig || !fieldConfig.validation_rules) {
        return undefined;
      }

      const maxLengthRule = fieldConfig.validation_rules.find(
        (rule: any) => rule.rule === 'max_length',
      );
      if (!maxLengthRule) {
        return undefined;
      }

      return maxLengthRule.value as number;
    },

    showErrorIcon(field_name: string, additional_field_error: any) {
      return (
        Array.isArray(additional_field_error) &&
        additional_field_error.some((error: any) => error.field === field_name)
      );
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const { lineItems, getTotalLineIndex, is_view_readonly } = storeToRefs(
      auto_accounting_store,
    );
    const {
      getDimensionsForAccount,
      validateLine,
      updateAccount: updateAccountInStore,
    } = auto_accounting_store;

    const accounting_type_store = useAccountingTypeStore();
    const { accounting_additional_fields } = storeToRefs(accounting_type_store);
    const { hasAdditionalFields, dynamicAdditionalFieldStyle } =
      accounting_type_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    return {
      user_settings,
      dynamicAdditionalFieldStyle,
      accounting_additional_fields,
      hasAdditionalFields,
      updateAccountInStore,
      getDimensionsForAccount,
      is_view_readonly,
      getTotalLineIndex,
      lineItems,
      header_index: ref(null as null | number),
      validateLine,
    };
  },
});
</script>
<style scoped lang="scss"></style>
