<template>
  <q-icon
    v-if="lineItems[index].split_items.length > 0"
    class="q-ml-sm cursor-pointer accounting-icon"
    tabindex="1"
    color="grey"
    size="sm"
    @click="un_splitLineItem"
    @keydown.enter="un_splitLineItem"
    :class="is_view_readonly || lineItems[index].readonly ? 'disabled' : ''"
  >
    <Icon icon="mdi:check-all" width="16" height="16" />
    <q-tooltip>{{ $t('remove_line_item_split') }}</q-tooltip>
  </q-icon>
</template>

<script lang="ts">

import { defineComponent } from 'vue';
import { useAutoAccountingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  mixins: [],
  props: {
    index: {
      type: Number,
      required: true,
    },
  },
  
  methods: {
    un_splitLineItem() {
      if (
        this.is_view_readonly ||
        this.lineItems[this.index].readonly === true
      ) {
        return;
      }
      this.lineItems[this.index].split_items = [];
      this.calculateTotalByMode();
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const { lineItems, is_view_readonly } = storeToRefs(auto_accounting_store);
    const { calculateTotalByMode } = auto_accounting_store;

    return {
      calculateTotalByMode,
      is_view_readonly,
      lineItems,
    };
  },
});
</script>
<style scoped lang="scss"></style>
