<template>
  <q-icon
    v-if="lineItems[index].split_items.length === 0"
    class="q-ml-sm cursor-pointer accounting-icon"
    tabindex="1"
    color="grey"
    size="sm"
    @click="splitLineItem"
    @keydown.enter="splitLineItem"
    :class="is_view_readonly || lineItems[index].readonly ? 'disabled' : ''"
  >
    <Icon icon="mdi:call-split" width="16" height="16" />
    <q-tooltip>{{ $t('split_line_item') }}</q-tooltip>
  </q-icon>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import { useAutoAccountingStore, useAmountFormatStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  mixins: [],
  props: {
    index: {
      type: Number,
      required: true,
    },
  },
  
  methods: {
    async splitLineItem() {
      if (
        this.is_view_readonly ||
        !this.lineItems[this.index].amount ||
        this.lineItems[this.index].amount === '' ||
        this.lineItems[this.index].readonly === true
      ) {
        return;
      }

      this.resetItem(this.index);

      let en_us_formatted_value = await this.formatValue(
        this.lineItems[this.index].amount,
        this.amount_format_locale,
      );
      const amount_standard = parseFloat(en_us_formatted_value);

      let half_value = amount_standard / 2;
      half_value = parseFloat(half_value.toFixed(2));
      let formatted_value = await this.formatValue(
        String(half_value),
        'en_US',
        this.amount_format_locale,
      );

      const line = this.baseSplitLineItem();
      line.percentage = '50%';
      line.amount = formatted_value;
      line.position = this.lineItems[this.index].position;
      this.inheritTaxCode(line, this.index);
      this.lineItems[this.index].split_items.push(line);

      const line_2 = this.baseSplitLineItem();
      line_2.percentage = '50%';
      line_2.amount = formatted_value;
      line_2.position = this.lineItems[this.index].position;
      this.inheritTaxCode(line_2, this.index);
      this.lineItems[this.index].split_items.push(line_2);

      this.calculateTotalByMode();
    },

    // M3 multi tax: both halves start on the same tax code as the parent line.
    // LN lines carry no tax_code, so nothing is added there.
    inheritTaxCode(line: any, parent_index: number) {
      if (!this.lineItems[parent_index].hasOwnProperty('tax_code')) {
        return;
      }
      line.tax_code = this.lineItems[parent_index].tax_code;
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const { lineItems, amount_format_locale, is_view_readonly } = storeToRefs(
      auto_accounting_store,
    );
    const { baseSplitLineItem, calculateTotalByMode, resetItem } =
      auto_accounting_store;

    const amount_format_store = useAmountFormatStore();
    const { formatValue } = amount_format_store;

    return {
      resetItem,
      calculateTotalByMode,
      baseSplitLineItem,
      is_view_readonly,
      amount_format_locale,
      formatValue,
      lineItems,
    };
  },
});
</script>
<style scoped lang="scss"></style>
