<template>
  <span
    class="account-link row cursor-pointer"
    @click="accountSelected(nodes.value)"
  >
    {{ nodes.label }}
  </span>
  <template v-if="nodes.children.length > 0">
    <ul class="childern account-categories-ul">
      <template v-for="(child, k) in nodes.children" :key="k">
        <li>
          <AccountCategory @accountSelected="accountSelected" :nodes="child" />
        </li>
      </template>
    </ul>
  </template>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
export default defineComponent({
  name: 'AccountCategory',
  props: {
    nodes: {
      type: Object,
      required: true,
    },
  },
  emits: ['accountSelected'],
  methods: {
    accountSelected(account: string) {
      this.$emit('accountSelected', account);
    },
  },
  setup() {
    return {};
  },
});
</script>
<style scoped lang="scss"></style>
