<template>
  <!-- Sub Line Items / Splited Items -->
  <template v-for="(item, child_index) in lineItems[index].split_items" :key="item" >
    <div class="full-width zebra-striping" :id="item.id" :data-id="item.id">
      <div class="accounting-fields-container">
        <div class="width-40 p-4"> </div>
        
        <div class="flex-1">
          <div class="row">
            <div
              class="p-4"
              :class="
                isMultiTaxSection ? 'primary-field' : 'primary-three-field'
              "
            >
              <Account
                :readonly="item.readonly"
                v-on:update-account="updateAccount"
                :item="item"
                :index="Number(child_index)"
              />
            </div>
            <div
              class="p-4"
              :class="
                isMultiTaxSection ? 'primary-field' : 'primary-three-field'
              "
            >
              <q-input
                class="full-width"
                tabindex="1"
                outlined
                dense
                v-model="
                  lineItems[index].split_items[child_index].booking_reference
                "
                :readonly="is_view_readonly ? true : false"
                maxlength="30"
              >
                <template v-slot:append>
                  <q-icon
                    flat
                    dense
                    name="error"
                    size="24px"
                    color="red"
                    v-if="false"
                  >
                    <q-tooltip
                      class="bg-red"
                      anchor="bottom right"
                      self="top right"
                    >
                      {{ $t('field_required') }}
                    </q-tooltip>
                  </q-icon>
                  <div
                    class="char-counter"
                    v-if="
                      lineItems[index].split_items[child_index]
                        .booking_reference
                    "
                  >
                    {{
                      lineItems[index].split_items[child_index]
                        .booking_reference.length
                    }}
                    / 30
                  </div>
                </template>
              </q-input>
              <q-tooltip  v-if="lineItems[index].split_items[child_index].booking_reference">{{ lineItems[index].split_items[child_index].booking_reference }}</q-tooltip>
           </div>
           <div :class="isMultiTaxSection ? 'secondary-field' : 'primary-three-field'">
            <div class="row">
              <div v-if="isMultiTaxSection" class="col-5 p-4">
                  <q-select
                    tabindex="1"
                    emit-value
                    map-options
                    outlined
                    dense
                    v-model="lineItems[index].split_items[child_index].position"
                    :options="taxCodeDropdown as any"
                    :readonly="is_view_readonly"
                  >
                  </q-select>
                  <q-tooltip anchor="center middle" self="top middle">{{ lineItems[index].split_items[child_index].position }}</q-tooltip>
              </div>
              <div class="p-4" :class="isMultiTaxSection ? 'col-7' : 'col-12'">
                <div class="row">
                  <div class="col-7">
                    <Amount :line_item_index="index" :split_line_index="Number(child_index)" />
                  </div>
                   <div class="col-5">
                     <Percent :line_item_index="index" :split_line_index="Number(child_index)" />
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div v-if="!is_view_readonly" class="w-75px p-4 p-t-10">
          <q-icon
            class="q-ml-sm cursor-pointer accounting-icon"
            tabindex="1"
            color="grey"
            size="xs"
            @click="deleteLineItem(Number(child_index), index)"
            @keydown.enter="deleteLineItem(Number(child_index), index)"
            :class="is_view_readonly ? 'disabled' : ''"
          >
            <Icon icon="mdi:delete" width="16" height="16" />
          </q-icon>
        </div>
      </div>
      
      <div class="row">      
        <div class="width-40"> </div>
    
        <div class="flex-1">
          <Dimensions
            :line_item_index="index"
            :split_line_index="Number(child_index)"
          />
        </div>
        <div v-if="!is_view_readonly" class="w-75px"></div>
      </div>
    </div>

    <div v-if="false && hasAdditionalFields()" class="primary-field p-4">
      <div
        v-for="(field, index) in accounting_additional_fields"
        :key="index"
        :style="dynamicAdditionalFieldStyle as any"
      >
        <q-input
          v-if="item.hasOwnProperty(field.field_name)"
          class="accouting-input column inline full-width"
          outlined
          v-model="item[field.field_name]"
          :readonly="is_view_readonly ? true : false"
          :counter="!!getFieldMaxLength(field.field_name)"
          :maxlength="getFieldMaxLength(field.field_name)"
        >
          <template v-slot:append>
            <q-icon
              v-if="
                showErrorIcon(
                  field.field_name,
                  additional_field_error[child_index],
                )
              "
              flat
              dense
              name="error"
              size="24px"
              color="red"
            >
              <q-tooltip class="bg-red" anchor="bottom right" self="top right">
                {{ $t('field_required') }}
              </q-tooltip>
            </q-icon>
          </template>
        </q-input>
      </div>
    </div>
  </template>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { validateAmount } from 'src/utils/validateRegex';
import Account from 'src/pages/AutoAccounting/Detail/components/Account.vue';
import Amount from 'src/pages/AutoAccounting/Detail/SplittedLineItem/Amount.vue';
import Percent from 'src/pages/AutoAccounting/Detail/SplittedLineItem/Percent.vue';
import Dimensions from 'src/pages/AutoAccounting/Detail/SplittedLineItem/Dimensions.vue';
import {
  useAccountingTypeStore,
  useAutoAccountingStore,
  useSettingStore,
} from 'src/store/main';

export default defineComponent({
  mixins: [cache],
  props: {
    index: {
      type: Number,
      required: true,
    },
    additional_field_error: {
      type: Array,
      default: () => [],
    },
  },
  components: {
    
    Account,
    Amount,
    Dimensions,
    Percent,
  },
  methods: {
    updateAccount(newValue: any) {
      if (this.is_view_readonly) {
        return;
      }

      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      const splitted_line_index = newValue.index;
      const account = newValue.value;

      this.updateAccountInStore(this.index, splitted_line_index, account);
    },

    validateAmountAndSetError(item: dynamicObj, value_float: any) {
      if (!value_float) {
        item.amount_error = this.$t('amount_is_empty');
        return false;
      }

      if (!validateAmount(value_float)) {
        item.amount_error = this.$t('amount_invalid');
        return false;
      }

      return true;
    },

    deleteLineItem(index: number, parentIndex: number) {
      if (this.is_view_readonly) {
        return;
      }
      try {
        this.lineItems[parentIndex].split_items.splice(index, 1);
      } catch (err) {
        logError(err);
      }
      this.calculateTotalByMode();
    },

    getFieldMaxLength(field_name: string) {
      const valid_booking_reference = this.user_settings[
        'AUTO_ACCOUNTING_FIELDS'
      ] as string;
      const fieldsConfig = JSON.parse(valid_booking_reference);

      const fieldConfig = fieldsConfig.find(
        (fieldConfig: any) => fieldConfig.field_name === field_name,
      );
      if (!fieldConfig || !fieldConfig.validation_rules) {
        return undefined;
      }

      const maxLengthRule = fieldConfig.validation_rules.find(
        (rule: any) => rule.rule === 'max_length',
      );
      if (!maxLengthRule) {
        return undefined;
      }

      return maxLengthRule.value as number;
    },

    showErrorIcon(field_name: string, additional_field_error: any) {
      const actual_field_error = additional_field_error.additional_field_error;
      return (
        Array.isArray(actual_field_error) &&
        actual_field_error.some((error: any) => error.field === field_name)
      );
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const {
      lineItems,
      is_view_readonly,
      isMultiTaxSection,
      taxCodeDropdown,
    } = storeToRefs(auto_accounting_store);
    const {
      calculateTotalByMode,
      getDimensionsForAccount,
      validateLine,
      updateAccount: updateAccountInStore,
    } = auto_accounting_store;

    const accounting_type_store = useAccountingTypeStore();
    const { accounting_additional_fields } = storeToRefs(accounting_type_store);
    const { hasAdditionalFields, dynamicAdditionalFieldStyle } =
      accounting_type_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    return {
      user_settings,
      hasAdditionalFields,
      dynamicAdditionalFieldStyle,
      accounting_additional_fields,
      taxCodeDropdown,
      getDimensionsForAccount,
      updateAccountInStore,
      calculateTotalByMode,
      isMultiTaxSection,
      is_view_readonly,
      validateLine,
      lineItems,
    };
  },
});
</script>
<style scoped lang="scss"></style>
