<template>
  <q-input
    tabindex="1"
    outlined
    dense
    debounce="500"
    v-model="lineItems[line_item_index].split_items[split_line_index].amount"
    @update:model-value="
      handleAmountEnter(
        lineItems[line_item_index].split_items[split_line_index],
      )
    "
    @keyup.enter="
      handleAmountEnter(
        lineItems[line_item_index].split_items[split_line_index],
      )
    "
    :readonly="is_view_readonly ? true : false"
  >
    <template v-slot:append>
      <q-icon
        v-if="
          lineItems[line_item_index].split_items[split_line_index][
            'amount_error'
          ] !== ''
        "
        flat
        dense
        name="error"
        size="24px"
        color="red"
      >
        <q-tooltip class="bg-red" anchor="bottom right" self="top right">
          {{
            lineItems[line_item_index].split_items[split_line_index][
              'amount_error'
            ]
          }}
        </q-tooltip>
      </q-icon>
    </template>
    <q-tooltip>{{
      lineItems[line_item_index].split_items[split_line_index].amount
    }}</q-tooltip>
  </q-input>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useAutoAccountingStore, useAmountFormatStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { validateAmount } from 'src/utils/validateRegex';

export default defineComponent({
  mixins: [],
  props: {
    line_item_index: {
      type: Number,
      required: true,
    },
    split_line_index: {
      type: Number,
      required: true,
    },
  },
  components: {},
  methods: {
    clearErrors(item: dynamicObj) {
      item.amount_error = '';
      item.percentage_error = '';
    },

    // using
    validateAmountAndSetError(item: dynamicObj, value_float: any) {
      if (!value_float) {
        item.amount_error = this.$t('amount_is_empty');
        return false;
      }

      if (!validateAmount(value_float, true)) {
        item.amount_error = this.$t('amount_invalid');
        return false;
      }

      return true;
    },

    //using
    validateAmountUpdateAndSetError(
      item: dynamicObj,
      value_float: number,
      original_amount_float: number,
    ) {
      if (!original_amount_float) {
        item.amount_error = this.$t('parent_amount_is_empty');
        return false;
      }

      let value1 = value_float;
      let value2 = original_amount_float;

      // for negitive values
      if (value1 < 0 && value2 < 0) {
        value1 = Math.abs(value1);
        value2 = Math.abs(value2);
      }

      if (value1 > value2) {
        // show error in amount field
        item.amount_error = this.$t(
          'amount_cannot_be_greater_than_parent_amount',
        );
        return false;
      }

      return true;
    },

    async handleAmountEnter(item: dynamicObj) {
      if (this.is_view_readonly) {
        return;
      }
      this.clearErrors(item);

      const item_amount = item.amount;
      if (!this.validateAmountAndSetError(item, item_amount)) {
        return;
      }

      const line_item_amount = this.lineItems[this.line_item_index].amount;

      const values = [];
      values.push({
        key: item_amount,
        value: item_amount,
      });

      values.push({
        key: line_item_amount,
        value: line_item_amount,
      });

      const result = await this.formatMultiValues(
        values,
        this.amount_format_locale,
      );

      const item_formatted_amount = this.searchValueByKey(item_amount, result);
      const item_amount_float = parseFloat(item_formatted_amount);
      if (!this.validateAmountAndSetError(item, item_amount_float)) {
        return;
      }
      item.amount_standard = item_amount_float;

      const line_item_formatted_amount = this.searchValueByKey(
        this.lineItems[this.line_item_index].amount,
        result,
      );
      const line_item_amount_float = parseFloat(line_item_formatted_amount);
      this.lineItems[this.line_item_index].amount_standard =
        line_item_amount_float;

      if (
        !this.validateAmountUpdateAndSetError(
          item,
          item_amount_float,
          line_item_amount_float,
        )
      ) {
        return;
      }

      const percentage = (item_amount_float / line_item_amount_float) * 100;
      item.percentage =
        (await this.formatValue(
          percentage.toFixed(2),
          'en_US',
          this.amount_format_locale,
        )) + '%';
      this.autFillEmptyLineItems(this.line_item_index);
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const { lineItems, amount_format_locale, is_view_readonly } = storeToRefs(
      auto_accounting_store,
    );

    const amount_format_store = useAmountFormatStore();
    const { formatMultiValues, formatValue } = amount_format_store;

    const { searchValueByKey, autFillEmptyLineItems } = auto_accounting_store;

    return {
      autFillEmptyLineItems,
      searchValueByKey,
      is_view_readonly,
      formatMultiValues,
      formatValue,
      amount_format_locale,
      lineItems,
    };
  },
});
</script>
<style scoped lang="scss"></style>
