<template>
  <!-- Dimensions -->
  <template v-if="dimensionsList.length > 0">
    <div class="row q-mb-sm">
      <div class="row full-width pl-16">{{ $t('dimensions') }}:</div>
      <template
        v-for="(obj, dimension_index) in dimensionsList"
        :key="obj.item.id"
      >
        <div
          class="p-4"
          :class="
            (Number(dimension_index) % 3 == 0 ? 'pl-16' : '') +
            ' ' +
            (isMultiTaxSection ? 'primary-field' : 'primary-three-field')
          "
        >
          <Dimension
            v-on:update-dimension="updateDimension"
            :item="obj.item"
            :index="obj.originalIndex"
            :account="
              lineItems[line_item_index].split_items[split_line_index].account
            "
          />
        </div>
      </template>
    </div>
  </template>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useAutoAccountingStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import Dimension from 'src/pages/AutoAccounting/Detail/components/Dimension.vue';

export default defineComponent({
  mixins: [],
  props: {
    line_item_index: {
      type: Number,
      required: true,
    },
    split_line_index: {
      type: Number,
      required: true,
    },
  },
  computed: {
    dimensionsList: function (): any {
      if (
        !this.lineItems[this.line_item_index].split_items[this.split_line_index]
          .dimensions ||
        this.lineItems[this.line_item_index].split_items[this.split_line_index]
          .dimensions.length == 0
      ) {
        return [];
      }
      return (
        this.lineItems[this.line_item_index].split_items[
          this.split_line_index
        ].dimensions
          .map((item: any, originalIndex: number) => ({
            item,
            originalIndex,
          }))
          .filter((obj: any) => obj.item.rule?.toLowerCase() !== 'p') || []
      );
    },
  },
  components: {
    Dimension,
  },
  methods: {
    updateDimension(newValue: any) {
      if (
        !newValue.hasOwnProperty('index') ||
        !newValue.hasOwnProperty('value')
      ) {
        return;
      }

      let value = newValue.value;
      if (value === undefined || value === null) {
        value = '';
      }
      this.lineItems[this.line_item_index].split_items[
        this.split_line_index
      ].dimensions[newValue.index].error = '';
      this.lineItems[this.line_item_index].split_items[
        this.split_line_index
      ].dimensions[newValue.index].value = value;
    },
  },
  setup() {
    const auto_accounting_store = useAutoAccountingStore();
    const { lineItems, dimensions, is_view_readonly, isMultiTaxSection } =
      storeToRefs(auto_accounting_store);

    return {
      isMultiTaxSection,
      is_view_readonly,
      dimensions,
      lineItems,
    };
  },
});
</script>
